// ---- begin stub/pmu_stub.sv ----
// -----------------------------------------------------------------------------
// pmu_stub.sv
//
// Minimal, synthesizable stand-in for the PD_AON Power Management Unit, used
// only as a verification vehicle for the UVM environment in verif/uvm/ while the
// real PMU RTL (rtl/) is developed on another branch.
//
// It implements the PMU behaviour from doc/SPEC.md at subsystem level:
//   * AXI4-Lite slave (32-bit address/data, one outstanding read and write).
//   * PD_CPU power sequencing:
//       power-down : clock gate -> isolation on -> reset assert
//                    -> [retention on, DEEP_SLEEP only] -> switch off
//       wake-up    : switch on -> wait power_good -> [retention off]
//                    -> reset release -> isolation off -> clock on
//   * CPU power states RUN / IDLE (clock gated on WFI) / SLEEP / DEEP_SLEEP.
//   * DVFS: 3 operating points, the clock-mux select only changes in IDLE.
//   * Isolation clamps on every PD_CPU -> PD_AON signal.
//   * A small register window that lives in PD_CPU; any access while PD_CPU is
//     not fully up (not RUN) returns SLVERR.
//
// SPEC.md does not define a PMU register map, so this stub defines one
// (documented in verif/uvm/README.md and mirrored by verif/uvm/ral/).
//
// Everything runs on clk_aon. The stub is NOT the deliverable PMU: it has no
// CDC logic because the testbench drives all PMU inputs synchronously.
//
// BUG_MODE (checker self-test only, 0 = correct behaviour):
//   1 : isolation is enabled before the clock is gated (sequencing order bug)
//   2 : PD_CPU window returns OKAY instead of SLVERR while powered off
//   3 : isolation clamp value is wrong (passes PD_CPU outputs through)
// -----------------------------------------------------------------------------
module pmu_stub #(
  parameter int unsigned IRQ_W       = 8,
  parameter int unsigned ISO_W       = 16,
  parameter logic [ISO_W-1:0] ISO_CLAMP = 16'h00F0,
  parameter logic [31:0] ID_VALUE    = 32'h504D_5501,
  parameter int unsigned BUG_MODE    = 0
) (
  input  logic              clk_aon,
  input  logic              rst_aon_n,

  // ---------------- AXI4-Lite slave ----------------
  input  logic [31:0]       s_axi_awaddr,
  input  logic [2:0]        s_axi_awprot,
  input  logic              s_axi_awvalid,
  output logic              s_axi_awready,
  input  logic [31:0]       s_axi_wdata,
  input  logic [3:0]        s_axi_wstrb,
  input  logic              s_axi_wvalid,
  output logic              s_axi_wready,
  output logic [1:0]        s_axi_bresp,
  output logic              s_axi_bvalid,
  input  logic              s_axi_bready,
  input  logic [31:0]       s_axi_araddr,
  input  logic [2:0]        s_axi_arprot,
  input  logic              s_axi_arvalid,
  output logic              s_axi_arready,
  output logic [31:0]       s_axi_rdata,
  output logic [1:0]        s_axi_rresp,
  output logic              s_axi_rvalid,
  input  logic              s_axi_rready,

  // ---------------- PD_CPU power control ----------------
  output logic              cpu_clk_en_o,    // 1 = clk_cpu running (clock gate open)
  output logic              cpu_iso_en_o,    // 1 = isolation clamps active
  output logic              cpu_ret_en_o,    // 1 = RAM retention mode
  output logic              cpu_pwr_en_o,    // 1 = power switch closed
  input  logic              cpu_pwr_good_i,  // power switch: supply is good
  output logic              cpu_rst_n_o,     // PD_CPU reset, active low
  output logic [1:0]        dvfs_sel_o,      // glitch-free clock mux select

  // ---------------- PD_CPU <-> PD_AON signals ----------------
  input  logic              cpu_wfi_i,       // CPU is in WFI
  input  logic [IRQ_W-1:0]  wake_irq_i,      // wake sources (level)
  input  logic [ISO_W-1:0]  pd_cpu_out_i,    // raw PD_CPU outputs
  output logic [ISO_W-1:0]  pd_cpu_out_iso_o // isolated outputs seen by PD_AON
);

  // ---------------------------------------------------------------------------
  // Register map (byte offsets)
  // ---------------------------------------------------------------------------
  localparam logic [11:0] A_ID        = 12'h000;
  localparam logic [11:0] A_CTRL      = 12'h004;
  localparam logic [11:0] A_STATUS    = 12'h008;
  localparam logic [11:0] A_DVFS      = 12'h00C;
  localparam logic [11:0] A_WAKE_MASK = 12'h010;
  localparam logic [11:0] A_WAKE_CAUSE= 12'h014;
  localparam logic [11:0] A_SEQ_DELAY = 12'h018;
  localparam logic [11:0] A_PD_COUNT  = 12'h01C;
  localparam logic [11:0] A_CPU_WIN   = 12'h100;   // 0x100..0x10C, PD_CPU

  localparam logic [1:0] RESP_OKAY   = 2'b00;
  localparam logic [1:0] RESP_SLVERR = 2'b10;
  localparam logic [1:0] RESP_DECERR = 2'b11;

  // STATUS.STATE encoding
  typedef enum logic [2:0] {
    ST_RUN   = 3'd0,
    ST_IDLE  = 3'd1,
    ST_SLEEP = 3'd2,
    ST_DEEP  = 3'd3,
    ST_PD    = 3'd4,   // power-down sequence in progress
    ST_PU    = 3'd5    // power-up sequence in progress
  } state_e;

  // ---------------------------------------------------------------------------
  // Registers
  // ---------------------------------------------------------------------------
  logic             ctrl_pd_en, ctrl_ret_en;
  logic [1:0]       dvfs_tgt;
  logic [IRQ_W-1:0] wake_mask, wake_cause;
  logic [7:0]       seq_delay;
  logic [15:0]      pd_count;
  logic [31:0]      cpu_win [4];

  state_e           state;
  logic [2:0]       step;
  logic [7:0]       dly_cnt;
  logic             mode_deep;     // latched RET_EN at WFI
  logic             wfi_q;

  wire              wfi_rise   = cpu_wfi_i & ~wfi_q;
  wire [IRQ_W-1:0]  wake_hit   = wake_irq_i & wake_mask;
  wire              wake       = |wake_hit;
  wire              dly_done   = (dly_cnt == 8'd0);
  wire [7:0]        dly_load   = (seq_delay == 8'd0) ? 8'd0 : seq_delay - 8'd1;
  wire              dvfs_pend  = (dvfs_tgt != dvfs_sel_o);
  wire              cpu_up     = (state == ST_RUN);

  // ---------------------------------------------------------------------------
  // AXI4-Lite write decode (AW and W accepted independently, one outstanding)
  // ---------------------------------------------------------------------------
  logic        aw_full, w_full;
  logic [31:0] aw_addr_q, w_data_q;
  logic [3:0]  w_strb_q;

  assign s_axi_awready = ~aw_full & ~s_axi_bvalid;
  assign s_axi_wready  = ~w_full  & ~s_axi_bvalid;

  wire        wr_fire = aw_full & w_full & ~s_axi_bvalid;
  wire [11:0] wr_off  = aw_addr_q[11:0];
  // Byte lane 0 after write strobes (only lane used by write-1-to-clear)
  wire [7:0]  wr_data_b0 = w_strb_q[0] ? w_data_q[7:0] : 8'h00;

  logic [1:0] wr_resp;
  always_comb begin
    wr_resp = RESP_OKAY;
    if (aw_addr_q[31:12] != '0 || aw_addr_q[1:0] != 2'b00) wr_resp = RESP_DECERR;
    else if (wr_off >= A_CPU_WIN && wr_off < A_CPU_WIN + 12'h010) begin
      if (!cpu_up && BUG_MODE != 2) wr_resp = RESP_SLVERR;
    end else begin
      unique case (wr_off)
        A_ID, A_STATUS, A_PD_COUNT, A_CTRL, A_WAKE_MASK, A_WAKE_CAUSE, A_SEQ_DELAY: ;
        A_DVFS:  if (w_strb_q[0] && w_data_q[1:0] == 2'd3) wr_resp = RESP_SLVERR; // reserved OPP
        default: wr_resp = RESP_DECERR;
      endcase
    end
  end
  wire wr_okay = (wr_resp == RESP_OKAY);

  // ---------------------------------------------------------------------------
  // Isolation cells
  // ---------------------------------------------------------------------------
  generate
    if (BUG_MODE == 3) begin : g_iso_bug
      assign pd_cpu_out_iso_o = pd_cpu_out_i;
    end else begin : g_iso
      assign pd_cpu_out_iso_o = cpu_iso_en_o ? ISO_CLAMP : pd_cpu_out_i;
    end
  endgenerate

  // ---------------------------------------------------------------------------
  // Power sequencer
  // ---------------------------------------------------------------------------
  always_ff @(posedge clk_aon or negedge rst_aon_n) begin
    if (!rst_aon_n) begin
      state        <= ST_PU;          // cold boot: bring PD_CPU up
      step         <= 3'd0;
      dly_cnt      <= 8'd3;
      mode_deep    <= 1'b0;
      wfi_q        <= 1'b0;
      cpu_clk_en_o <= 1'b0;
      cpu_iso_en_o <= 1'b1;
      cpu_ret_en_o <= 1'b0;
      cpu_pwr_en_o <= 1'b0;
      cpu_rst_n_o  <= 1'b0;
      dvfs_sel_o   <= 2'd0;
      pd_count     <= 16'd0;
      wake_cause   <= '0;
    end else begin
      wfi_q <= cpu_wfi_i;
      if (!dly_done) dly_cnt <= dly_cnt - 8'd1;

      unique case (state)
        ST_RUN: begin
          if (wfi_rise) begin
            mode_deep <= ctrl_ret_en;
            dly_cnt   <= dly_load;
            step      <= 3'd0;
            if (ctrl_pd_en) begin
              state <= ST_PD;
              if (BUG_MODE == 1) cpu_iso_en_o <= 1'b1;   // wrong order
              else               cpu_clk_en_o <= 1'b0;
            end else begin
              state        <= ST_IDLE;
              cpu_clk_en_o <= 1'b0;
            end
          end
        end

        ST_IDLE: begin
          // DVFS: the mux is only switched while the clock is gated in IDLE.
          if (dvfs_pend && (dly_done || wake)) begin
            dvfs_sel_o <= dvfs_tgt;
            dly_cnt    <= dly_load;
          end else if (wake && dly_done) begin
            wake_cause   <= wake_cause | wake_hit;
            cpu_clk_en_o <= 1'b1;
            state        <= ST_RUN;
          end
        end

        ST_PD: begin
          if (dly_done) begin
            dly_cnt <= dly_load;
            step    <= step + 3'd1;
            unique case (step)
              3'd0: if (BUG_MODE == 1) cpu_clk_en_o <= 1'b0;
                    else               cpu_iso_en_o <= 1'b1;
              3'd1: cpu_rst_n_o  <= 1'b0;
              3'd2: if (mode_deep) cpu_ret_en_o <= 1'b1;
                    else begin cpu_pwr_en_o <= 1'b0; state <= ST_SLEEP; pd_count <= pd_count + 16'd1; end
              3'd3: begin cpu_pwr_en_o <= 1'b0; state <= ST_DEEP; pd_count <= pd_count + 16'd1; end
              default: ;
            endcase
          end
        end

        ST_SLEEP, ST_DEEP: begin
          if (wake && dly_done) begin
            wake_cause   <= wake_cause | wake_hit;
            cpu_pwr_en_o <= 1'b1;
            state        <= ST_PU;
            step         <= 3'd0;
            dly_cnt      <= dly_load;
          end
        end

        ST_PU: begin
          // step 0: switch on (also the cold-boot entry point)
          // step 1: wait power_good, then retention off (if set)
          // step 2: reset release, 3: isolation off, 4: clock on
          if (dly_done) begin
            unique case (step)
              3'd0: begin cpu_pwr_en_o <= 1'b1; step <= 3'd1; dly_cnt <= dly_load; end
              3'd1: if (cpu_pwr_good_i) begin
                      dly_cnt <= dly_load;
                      if (cpu_ret_en_o) cpu_ret_en_o <= 1'b0;
                      else begin cpu_rst_n_o <= 1'b1; step <= 3'd3; end
                    end
              3'd3: begin cpu_iso_en_o <= 1'b0; step <= 3'd4; dly_cnt <= dly_load; end
              3'd4: begin cpu_clk_en_o <= 1'b1; state <= ST_RUN; end
              default: step <= 3'd0;
            endcase
          end
        end

        default: state <= ST_PU;
      endcase

      // WAKE_CAUSE is write-1-to-clear (bus write handled below has priority)
      if (wr_fire && wr_off == A_WAKE_CAUSE && wr_okay)
        wake_cause <= wake_cause & ~wr_data_b0[IRQ_W-1:0];
    end
  end

  // ---------------------------------------------------------------------------
  // AXI4-Lite write channel
  // ---------------------------------------------------------------------------
  always_ff @(posedge clk_aon or negedge rst_aon_n) begin
    if (!rst_aon_n) begin
      aw_full <= 1'b0; w_full <= 1'b0; s_axi_bvalid <= 1'b0; s_axi_bresp <= RESP_OKAY;
      aw_addr_q <= '0; w_data_q <= '0; w_strb_q <= '0;
      ctrl_pd_en <= 1'b0; ctrl_ret_en <= 1'b0; dvfs_tgt <= 2'd0;
      wake_mask <= '1; seq_delay <= 8'd4;
    end else begin
      if (s_axi_awvalid && s_axi_awready) begin aw_full <= 1'b1; aw_addr_q <= s_axi_awaddr; end
      if (s_axi_wvalid  && s_axi_wready)  begin w_full  <= 1'b1; w_data_q <= s_axi_wdata; w_strb_q <= s_axi_wstrb; end
      if (s_axi_bvalid && s_axi_bready) s_axi_bvalid <= 1'b0;
      if (wr_fire) begin
        aw_full <= 1'b0; w_full <= 1'b0;
        s_axi_bvalid <= 1'b1;
        s_axi_bresp  <= wr_resp;
        if (wr_okay) begin
          unique case (wr_off)
            A_CTRL:      begin
                           if (w_strb_q[0]) begin ctrl_pd_en <= w_data_q[0]; ctrl_ret_en <= w_data_q[1]; end
                         end
            A_DVFS:      if (w_strb_q[0]) dvfs_tgt  <= w_data_q[1:0];
            A_WAKE_MASK: if (w_strb_q[0]) wake_mask <= w_data_q[IRQ_W-1:0];
            A_SEQ_DELAY: if (w_strb_q[0]) seq_delay <= w_data_q[7:0];
            default: ;
          endcase
        end
      end
    end
  end

  // PD_CPU register window: reset whenever PD_CPU is in reset / powered off.
  always_ff @(posedge clk_aon or negedge rst_aon_n) begin
    if (!rst_aon_n) begin
      for (int i = 0; i < 4; i++) cpu_win[i] <= '0;
    end else if (!cpu_rst_n_o) begin
      for (int i = 0; i < 4; i++) cpu_win[i] <= '0;
    end else if (wr_fire && wr_okay && wr_off >= A_CPU_WIN && wr_off < A_CPU_WIN + 12'h010 && cpu_up) begin
      for (int b = 0; b < 4; b++)
        if (w_strb_q[b]) cpu_win[wr_off[3:2]][8*b +: 8] <= w_data_q[8*b +: 8];
    end
  end

  // ---------------------------------------------------------------------------
  // AXI4-Lite read channel
  // ---------------------------------------------------------------------------
  assign s_axi_arready = ~s_axi_rvalid;

  logic [31:0] rd_data;
  logic [1:0]  rd_resp;
  wire  [11:0] rd_off = s_axi_araddr[11:0];
  always_comb begin
    rd_data = '0;
    rd_resp = RESP_OKAY;
    if (s_axi_araddr[31:12] != '0 || s_axi_araddr[1:0] != 2'b00) rd_resp = RESP_DECERR;
    else if (rd_off >= A_CPU_WIN && rd_off < A_CPU_WIN + 12'h010) begin
      if (!cpu_up && BUG_MODE != 2) rd_resp = RESP_SLVERR;
      else                          rd_data = cpu_win[rd_off[3:2]];
    end else begin
      unique case (rd_off)
        A_ID:         rd_data = ID_VALUE;
        A_CTRL:       rd_data = {30'd0, ctrl_ret_en, ctrl_pd_en};
        A_STATUS:     rd_data = {15'd0, dvfs_pend, 2'd0, dvfs_sel_o, 2'd0,
                                 cpu_rst_n_o, cpu_pwr_good_i, cpu_pwr_en_o, cpu_ret_en_o,
                                 cpu_iso_en_o, cpu_clk_en_o, 1'b0, state};
        A_DVFS:       rd_data = {30'd0, dvfs_tgt};
        A_WAKE_MASK:  rd_data = {{(32-IRQ_W){1'b0}}, wake_mask};
        A_WAKE_CAUSE: rd_data = {{(32-IRQ_W){1'b0}}, wake_cause};
        A_SEQ_DELAY:  rd_data = {24'd0, seq_delay};
        A_PD_COUNT:   rd_data = {16'd0, pd_count};
        default:      rd_resp = RESP_DECERR;
      endcase
    end
  end

  always_ff @(posedge clk_aon or negedge rst_aon_n) begin
    if (!rst_aon_n) begin
      s_axi_rvalid <= 1'b0; s_axi_rdata <= '0; s_axi_rresp <= RESP_OKAY;
    end else begin
      if (s_axi_rvalid && s_axi_rready) s_axi_rvalid <= 1'b0;
      if (s_axi_arvalid && s_axi_arready) begin
        s_axi_rvalid <= 1'b1;
        s_axi_rdata  <= rd_data;
        s_axi_rresp  <= rd_resp;
      end
    end
  end

  // Unused inputs (protection type is not checked by this stub)
  wire unused_ok = &{1'b0, s_axi_awprot, s_axi_arprot};

endmodule
// ---- end stub/pmu_stub.sv ----

// ---- begin agents/axi_lite/axi_lite_if.sv ----
// -----------------------------------------------------------------------------
// axi_lite_if.sv - AXI4-Lite interface (32-bit address, 32-bit data)
//
// Reusable: carries no DUT-specific information. The master driver uses
// drv_cb, the passive monitor uses mon_cb. Protocol assertions live in
// axi_lite_protocol_checker.sv and are bound to this interface.
// -----------------------------------------------------------------------------
interface axi_lite_if (input logic aclk, input logic aresetn);

  logic [31:0] awaddr;
  logic [2:0]  awprot;
  logic        awvalid;
  logic        awready;
  logic [31:0] wdata;
  logic [3:0]  wstrb;
  logic        wvalid;
  logic        wready;
  logic [1:0]  bresp;
  logic        bvalid;
  logic        bready;
  logic [31:0] araddr;
  logic [2:0]  arprot;
  logic        arvalid;
  logic        arready;
  logic [31:0] rdata;
  logic [1:0]  rresp;
  logic        rvalid;
  logic        rready;

  clocking drv_cb @(posedge aclk);
    default input #1step output #1;
    output awaddr, awprot, awvalid, wdata, wstrb, wvalid, bready,
           araddr, arprot, arvalid, rready;
    input  awready, wready, bresp, bvalid, arready, rdata, rresp, rvalid;
  endclocking

  clocking mon_cb @(posedge aclk);
    default input #1step;
    input awaddr, awprot, awvalid, awready, wdata, wstrb, wvalid, wready,
          bresp, bvalid, bready, araddr, arprot, arvalid, arready,
          rdata, rresp, rvalid, rready;
  endclocking

  // Master-side reset values (called by the driver while aresetn is low)
  task automatic master_reset();
    awvalid <= 1'b0;
    wvalid  <= 1'b0;
    arvalid <= 1'b0;
    bready  <= 1'b0;
    rready  <= 1'b0;
    awaddr  <= '0;
    awprot  <= '0;
    wdata   <= '0;
    wstrb   <= '0;
    araddr  <= '0;
    arprot  <= '0;
  endtask

endinterface
// ---- end agents/axi_lite/axi_lite_if.sv ----

// ---- begin agents/axi_lite/axi_lite_protocol_checker.sv ----
// -----------------------------------------------------------------------------
// axi_lite_protocol_checker.sv - AXI4-Lite protocol assertions and covers
//
// Bound to every axi_lite_if instance (see tb/axi_lite_bind.sv). Checks the
// AMBA AXI4 (IHI0022) rules that apply to AXI4-Lite:
//   * VALID must stay asserted, and payload stable, until the handshake
//   * no X/Z on VALID/READY out of reset, no X/Z on payload while VALID
//   * all VALIDs low while ARESETn is asserted
//   * B only after both AW and W handshakes of that write; R only after AR
//   * EXOKAY is not a legal AXI4-Lite response
//   * bounded response latency (MAX_WAIT cycles; 0 disables)
// -----------------------------------------------------------------------------
module axi_lite_protocol_checker #(
  parameter int unsigned MAX_WAIT = 256
) (
  input logic        aclk,
  input logic        aresetn,
  input logic [31:0] awaddr,
  input logic [2:0]  awprot,
  input logic        awvalid,
  input logic        awready,
  input logic [31:0] wdata,
  input logic [3:0]  wstrb,
  input logic        wvalid,
  input logic        wready,
  input logic [1:0]  bresp,
  input logic        bvalid,
  input logic        bready,
  input logic [31:0] araddr,
  input logic [2:0]  arprot,
  input logic        arvalid,
  input logic        arready,
  input logic [31:0] rdata,
  input logic [1:0]  rresp,
  input logic        rvalid,
  input logic        rready
);

  localparam logic [1:0] EXOKAY = 2'b01;

  // ---------------------------------------------------------------------------
  // Handshake stability: once VALID is high it stays high with stable payload
  // until READY.
  // ---------------------------------------------------------------------------
  property p_hold(logic valid, logic ready);
    @(posedge aclk) disable iff (!aresetn)
      (valid && !ready) |=> valid;
  endproperty

  a_aw_hold: assert property (p_hold(awvalid, awready)) else $error("AXI-L: AWVALID dropped before AWREADY");
  a_w_hold:  assert property (p_hold(wvalid,  wready))  else $error("AXI-L: WVALID dropped before WREADY");
  a_b_hold:  assert property (p_hold(bvalid,  bready))  else $error("AXI-L: BVALID dropped before BREADY");
  a_ar_hold: assert property (p_hold(arvalid, arready)) else $error("AXI-L: ARVALID dropped before ARREADY");
  a_r_hold:  assert property (p_hold(rvalid,  rready))  else $error("AXI-L: RVALID dropped before RREADY");

  a_aw_stable: assert property (@(posedge aclk) disable iff (!aresetn)
      (awvalid && !awready) |=> ($stable(awaddr) && $stable(awprot)))
    else $error("AXI-L: AW payload changed while AWVALID && !AWREADY");
  a_w_stable: assert property (@(posedge aclk) disable iff (!aresetn)
      (wvalid && !wready) |=> ($stable(wdata) && $stable(wstrb)))
    else $error("AXI-L: W payload changed while WVALID && !WREADY");
  a_b_stable: assert property (@(posedge aclk) disable iff (!aresetn)
      (bvalid && !bready) |=> $stable(bresp))
    else $error("AXI-L: BRESP changed while BVALID && !BREADY");
  a_ar_stable: assert property (@(posedge aclk) disable iff (!aresetn)
      (arvalid && !arready) |=> ($stable(araddr) && $stable(arprot)))
    else $error("AXI-L: AR payload changed while ARVALID && !ARREADY");
  a_r_stable: assert property (@(posedge aclk) disable iff (!aresetn)
      (rvalid && !rready) |=> ($stable(rdata) && $stable(rresp)))
    else $error("AXI-L: R payload changed while RVALID && !RREADY");

  // ---------------------------------------------------------------------------
  // Legal responses
  // ---------------------------------------------------------------------------
  a_b_no_exokay: assert property (@(posedge aclk) disable iff (!aresetn)
      bvalid |-> (bresp != EXOKAY)) else $error("AXI-L: EXOKAY on BRESP");
  a_r_no_exokay: assert property (@(posedge aclk) disable iff (!aresetn)
      rvalid |-> (rresp != EXOKAY)) else $error("AXI-L: EXOKAY on RRESP");

  // ---------------------------------------------------------------------------
  // Reset: all VALIDs low while ARESETn asserted (sampled on the clock)
  // ---------------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      a_rst_valids: assert (!awvalid && !wvalid && !arvalid && !bvalid && !rvalid)
        else $error("AXI-L: VALID asserted during reset");
    end
  end

  // ---------------------------------------------------------------------------
  // X/Z checks
  // ---------------------------------------------------------------------------
  always @(posedge aclk) begin
    if (aresetn) begin
      a_ctrl_known: assert (!$isunknown({awvalid, awready, wvalid, wready, bvalid, bready,
                                          arvalid, arready, rvalid, rready}))
        else $error("AXI-L: X/Z on a VALID/READY signal");
      if (awvalid) a_aw_known: assert (!$isunknown({awaddr, awprot})) else $error("AXI-L: X/Z on AW payload");
      if (wvalid)  a_w_known:  assert (!$isunknown({wdata, wstrb}))   else $error("AXI-L: X/Z on W payload");
      if (bvalid)  a_b_known:  assert (!$isunknown(bresp))            else $error("AXI-L: X/Z on BRESP");
      if (arvalid) a_ar_known: assert (!$isunknown({araddr, arprot})) else $error("AXI-L: X/Z on AR payload");
      if (rvalid)  a_r_known:  assert (!$isunknown({rdata, rresp}))   else $error("AXI-L: X/Z on R payload");
    end
  end

  // ---------------------------------------------------------------------------
  // Transaction ordering: count handshakes. A write response may only be
  // given for a write whose AW and W have both been accepted; a read response
  // only for an accepted AR.
  // ---------------------------------------------------------------------------
  int unsigned aw_cnt, w_cnt, b_cnt, ar_cnt, r_cnt;
  int unsigned b_wait, r_wait;

  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      aw_cnt <= 0; w_cnt <= 0; b_cnt <= 0; ar_cnt <= 0; r_cnt <= 0;
      b_wait <= 0; r_wait <= 0;
    end else begin
      if (bvalid) begin
        a_b_after_aw_w: assert ((aw_cnt > b_cnt) && (w_cnt > b_cnt))
          else $error("AXI-L: BVALID without a completed AW+W (aw=%0d w=%0d b=%0d)", aw_cnt, w_cnt, b_cnt);
      end
      if (rvalid) begin
        a_r_after_ar: assert (ar_cnt > r_cnt)
          else $error("AXI-L: RVALID without an accepted AR (ar=%0d r=%0d)", ar_cnt, r_cnt);
      end
      if (awvalid && awready) aw_cnt <= aw_cnt + 1;
      if (wvalid  && wready)  w_cnt  <= w_cnt  + 1;
      if (bvalid  && bready)  b_cnt  <= b_cnt  + 1;
      if (arvalid && arready) ar_cnt <= ar_cnt + 1;
      if (rvalid  && rready)  r_cnt  <= r_cnt  + 1;

      // Response latency watchdog: writes/reads accepted but not answered.
      if ((aw_cnt > b_cnt) && (w_cnt > b_cnt) && !bvalid) b_wait <= b_wait + 1; else b_wait <= 0;
      if ((ar_cnt > r_cnt) && !rvalid)                    r_wait <= r_wait + 1; else r_wait <= 0;
      if (MAX_WAIT != 0) begin
        a_b_latency: assert (b_wait < MAX_WAIT) else $error("AXI-L: no BVALID within %0d cycles", MAX_WAIT);
        a_r_latency: assert (r_wait < MAX_WAIT) else $error("AXI-L: no RVALID within %0d cycles", MAX_WAIT);
      end
    end
  end

  // ---------------------------------------------------------------------------
  // Protocol coverage
  // ---------------------------------------------------------------------------
  c_aw_before_w:   cover property (@(posedge aclk) disable iff (!aresetn) (awvalid && awready && !wvalid));
  c_w_before_aw:   cover property (@(posedge aclk) disable iff (!aresetn) (wvalid && wready && !awvalid));
  c_aw_w_same:     cover property (@(posedge aclk) disable iff (!aresetn) (awvalid && awready && wvalid && wready));
  c_aw_wait:       cover property (@(posedge aclk) disable iff (!aresetn) (awvalid && !awready));
  c_b_backpress:   cover property (@(posedge aclk) disable iff (!aresetn) (bvalid && !bready));
  c_r_backpress:   cover property (@(posedge aclk) disable iff (!aresetn) (rvalid && !rready));
  c_b_slverr:      cover property (@(posedge aclk) disable iff (!aresetn) (bvalid && bready && bresp == 2'b10));
  c_b_decerr:      cover property (@(posedge aclk) disable iff (!aresetn) (bvalid && bready && bresp == 2'b11));
  c_r_slverr:      cover property (@(posedge aclk) disable iff (!aresetn) (rvalid && rready && rresp == 2'b10));
  c_r_decerr:      cover property (@(posedge aclk) disable iff (!aresetn) (rvalid && rready && rresp == 2'b11));
  c_rd_wr_overlap: cover property (@(posedge aclk) disable iff (!aresetn) (arvalid && awvalid));

endmodule
// ---- end agents/axi_lite/axi_lite_protocol_checker.sv ----

// ---- begin agents/pwr/pwr_if.sv ----
// -----------------------------------------------------------------------------
// pwr_if.sv - power control/status interface between a PMU and one switchable
// power domain (here PD_CPU).
//
// Monitored (PMU outputs): clock gate enable, isolation enable, retention
// enable, power switch enable, domain reset, DVFS clock-mux select, and the
// isolated domain outputs as seen by the always-on side.
// Driven by the agent (models the power switch, the CPU and wake sources):
// power_good, WFI, wake interrupts and the raw (pre-isolation) domain outputs.
//
// Widths are fixed by macros so the virtual interface type stays simple;
// override with +define+PWR_IRQ_W=<n> / +define+PWR_ISO_W=<n> if needed.
// -----------------------------------------------------------------------------

// ---- begin agents/pwr/pwr_defines.svh ----
// pwr_defines.svh - widths of the power interface (override with +define+)
`ifndef PWR_DEFINES_SVH
`define PWR_DEFINES_SVH
  `ifndef PWR_IRQ_W
    `define PWR_IRQ_W 8
  `endif
  `ifndef PWR_ISO_W
    `define PWR_ISO_W 16
  `endif
`endif
// ---- end agents/pwr/pwr_defines.svh ----

interface pwr_if (input logic clk, input logic rst_n);

  // PMU -> domain controls
  logic                  clk_en;      // 1 = domain clock running
  logic                  iso_en;      // 1 = isolation clamps on
  logic                  ret_en;      // 1 = retention mode
  logic                  pwr_en;      // 1 = power switch on
  logic                  dom_rst_n;   // domain reset, active low
  logic [1:0]            dvfs_sel;    // clock-mux select (operating point)

  // switch / domain / wake sources -> PMU
  logic                  pwr_good;
  logic                  wfi;
  logic [`PWR_IRQ_W-1:0] wake_irq;
  logic [`PWR_ISO_W-1:0] dom_out;     // raw domain outputs
  logic [`PWR_ISO_W-1:0] dom_out_iso; // after isolation cells (AON side)

  clocking drv_cb @(posedge clk);
    default input #1step output #1;
    output pwr_good, wfi, wake_irq, dom_out;
    input  clk_en, iso_en, ret_en, pwr_en, dom_rst_n, dvfs_sel, dom_out_iso;
  endclocking

  clocking mon_cb @(posedge clk);
    default input #1step;
    input clk_en, iso_en, ret_en, pwr_en, dom_rst_n, dvfs_sel,
          pwr_good, wfi, wake_irq, dom_out, dom_out_iso;
  endclocking

  task automatic drive_reset();
    pwr_good <= 1'b0;
    wfi      <= 1'b0;
    wake_irq <= '0;
    dom_out  <= '0;
  endtask

endinterface
// ---- end agents/pwr/pwr_if.sv ----

// ---- begin agents/axi_lite/axi_lite_pkg.sv ----
// -----------------------------------------------------------------------------
// axi_lite_pkg.sv - reusable AXI4-Lite master agent (UVM, IEEE 1800.2)
//
//   axi_lite_cfg           agent configuration (vif, active/passive, coverage)
//   axi_lite_item          one read or write, with per-channel delays
//   axi_lite_driver        master driver (AW/W independent, B/R back-pressure)
//   axi_lite_monitor       passive monitor, timestamps every handshake
//   axi_lite_coverage      protocol-level functional coverage
//   axi_lite_agent         container
//   axi_lite_reg_adapter   uvm_reg <-> axi_lite_item adapter
//   sequences              single / back-to-back / random-delay / error
// -----------------------------------------------------------------------------
package axi_lite_pkg;

  import uvm_pkg::*;
  `include "uvm_macros.svh"

  typedef enum bit { AXI_READ = 1'b0, AXI_WRITE = 1'b1 } axi_lite_kind_e;

  typedef enum bit [1:0] {
    AXI_OKAY   = 2'b00,
    AXI_EXOKAY = 2'b01,   // illegal in AXI4-Lite, listed for completeness
    AXI_SLVERR = 2'b10,
    AXI_DECERR = 2'b11
  } axi_lite_resp_e;

  // Delay profile used by sequences to bias the per-channel delays
  typedef enum { AXI_DLY_ZERO, AXI_DLY_SHORT, AXI_DLY_RANDOM, AXI_DLY_LONG } axi_lite_dly_e;


// ---- begin agents/axi_lite/axi_lite_cfg.svh ----
// axi_lite_cfg.svh - AXI4-Lite agent configuration
class axi_lite_cfg extends uvm_object;

  virtual axi_lite_if vif;

  uvm_active_passive_enum is_active = UVM_ACTIVE;
  bit has_coverage                  = 1;

  // Drive random values on payload signals while VALID is low, to catch a
  // slave that samples payload without a handshake.
  bit rand_idle_payload             = 1;

  // Driver gives up (uvm_error) if a handshake takes longer than this.
  int unsigned handshake_timeout    = 1000;

  // Default delay profile for items that do not constrain their delays.
  axi_lite_dly_e default_dly        = AXI_DLY_RANDOM;

  `uvm_object_utils_begin(axi_lite_cfg)
    `uvm_field_enum(uvm_active_passive_enum, is_active, UVM_DEFAULT)
    `uvm_field_int(has_coverage, UVM_DEFAULT)
    `uvm_field_int(rand_idle_payload, UVM_DEFAULT)
    `uvm_field_int(handshake_timeout, UVM_DEFAULT | UVM_DEC)
    `uvm_field_enum(axi_lite_dly_e, default_dly, UVM_DEFAULT)
  `uvm_object_utils_end

  function new(string name = "axi_lite_cfg");
    super.new(name);
  endfunction

endclass
// ---- end agents/axi_lite/axi_lite_cfg.svh ----

// ---- begin agents/axi_lite/axi_lite_item.svh ----
// axi_lite_item.svh - one AXI4-Lite read or write transaction
class axi_lite_item extends uvm_sequence_item;

  // ---------------- request ----------------
  rand axi_lite_kind_e kind;
  rand bit [31:0]      addr;
  rand bit [31:0]      data;     // write data, or read data after completion
  rand bit [3:0]       strb;
  rand bit [2:0]       prot;

  // ---------------- timing (in clock cycles) ----------------
  rand axi_lite_dly_e  dly_mode;
  rand int unsigned    aw_delay;     // before AWVALID
  rand int unsigned    w_delay;      // before WVALID (relative to item start)
  rand int unsigned    ar_delay;     // before ARVALID
  rand int unsigned    bready_delay; // before BREADY
  rand int unsigned    rready_delay; // before RREADY

  // ---------------- response (filled by driver / monitor) ----------------
  axi_lite_resp_e      resp;

  // Monitor timestamps (simulation time) of the handshakes.
  realtime             t_req;   // first request-channel handshake (AW, W or AR)
  realtime             t_exec;  // last request-channel handshake (AW and W done / AR)
  realtime             t_resp;  // B or R handshake
  int unsigned         req_wait;   // cycles VALID was waiting for READY (request)
  int unsigned         resp_wait;  // cycles B/RVALID waited for B/RREADY
  int unsigned         gap;        // idle cycles since previous transaction (same dir)

  constraint c_align  { addr[1:0] == 2'b00; }
  constraint c_strb   { kind == AXI_READ -> strb == 4'hF;
                        strb dist { 4'hF := 9, [4'h0:4'hE] :/ 1 }; }
  constraint c_prot   { soft prot == 3'b000; }
  constraint c_dlymode{ soft dly_mode == AXI_DLY_RANDOM; }

  constraint c_delays {
    aw_delay <= 64; w_delay <= 64; ar_delay <= 64; bready_delay <= 64; rready_delay <= 64;
    if (dly_mode == AXI_DLY_ZERO) {
      aw_delay == 0; w_delay == 0; ar_delay == 0; bready_delay == 0; rready_delay == 0;
    } else if (dly_mode == AXI_DLY_SHORT) {
      aw_delay <= 2; w_delay <= 2; ar_delay <= 2; bready_delay <= 2; rready_delay <= 2;
    } else if (dly_mode == AXI_DLY_RANDOM) {
      aw_delay     dist { 0 := 6, [1:3] := 3, [4:10] := 1 };
      w_delay      dist { 0 := 6, [1:3] := 3, [4:10] := 1 };
      ar_delay     dist { 0 := 6, [1:3] := 3, [4:10] := 1 };
      bready_delay dist { 0 := 6, [1:3] := 3, [4:10] := 1 };
      rready_delay dist { 0 := 6, [1:3] := 3, [4:10] := 1 };
    } else {
      aw_delay inside {[10:64]}; w_delay inside {[0:64]}; ar_delay inside {[10:64]};
      bready_delay inside {[5:64]}; rready_delay inside {[5:64]};
    }
  }

  `uvm_object_utils_begin(axi_lite_item)
    `uvm_field_enum(axi_lite_kind_e, kind, UVM_DEFAULT)
    `uvm_field_int(addr, UVM_DEFAULT)
    `uvm_field_int(data, UVM_DEFAULT)
    `uvm_field_int(strb, UVM_DEFAULT)
    `uvm_field_int(prot, UVM_DEFAULT)
    `uvm_field_enum(axi_lite_resp_e, resp, UVM_DEFAULT)
    `uvm_field_int(aw_delay, UVM_DEFAULT | UVM_DEC | UVM_NOCOMPARE)
    `uvm_field_int(w_delay, UVM_DEFAULT | UVM_DEC | UVM_NOCOMPARE)
    `uvm_field_int(ar_delay, UVM_DEFAULT | UVM_DEC | UVM_NOCOMPARE)
    `uvm_field_int(bready_delay, UVM_DEFAULT | UVM_DEC | UVM_NOCOMPARE)
    `uvm_field_int(rready_delay, UVM_DEFAULT | UVM_DEC | UVM_NOCOMPARE)
  `uvm_object_utils_end

  function new(string name = "axi_lite_item");
    super.new(name);
  endfunction

  function string convert2string();
    return $sformatf("%s addr=0x%08h data=0x%08h strb=%b resp=%s t=[%0t..%0t]",
                     kind == AXI_WRITE ? "WR" : "RD", addr, data, strb, resp.name(), t_req, t_resp);
  endfunction

endclass
// ---- end agents/axi_lite/axi_lite_item.svh ----

// ---- begin agents/axi_lite/axi_lite_sequencer.svh ----
// axi_lite_sequencer.svh
class axi_lite_sequencer extends uvm_sequencer #(axi_lite_item);
  `uvm_component_utils(axi_lite_sequencer)

  axi_lite_cfg cfg;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction
endclass
// ---- end agents/axi_lite/axi_lite_sequencer.svh ----

// ---- begin agents/axi_lite/axi_lite_driver.svh ----
// axi_lite_driver.svh - AXI4-Lite master driver
//
// One transaction at a time (AXI4-Lite slaves commonly accept one outstanding
// access). Back-to-back items are driven without idle cycles when all delays
// are zero. For writes AW and W are driven by independent threads so that
// AW-before-W, W-before-AW and simultaneous orders are all exercised.
// The response (resp, read data) is written back into the request item.
class axi_lite_driver extends uvm_driver #(axi_lite_item);
  `uvm_component_utils(axi_lite_driver)

  axi_lite_cfg        cfg;
  virtual axi_lite_if vif;

  // Time of the most recent drv_cb clocking event. A synchronous drive issued
  // in that time step takes effect at that edge; issued later (e.g. when a
  // sequence produces an item between edges) it would only take effect at
  // the next edge, so the driver first re-aligns to the clock.
  protected realtime last_edge = -1;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (cfg == null) `uvm_fatal("CFG", "axi_lite_driver: cfg not set")
    vif = cfg.vif;
  endfunction

  task run_phase(uvm_phase phase);
    axi_lite_item req;
    vif.master_reset();
    fork
      forever begin
        @(vif.drv_cb);
        last_edge = $realtime;
      end
    join_none
    forever begin
      // Hold idle while in reset
      while (vif.aresetn !== 1'b1) begin
        vif.master_reset();
        @(posedge vif.aclk);
      end
      seq_item_port.get_next_item(req);
      if ($realtime != last_edge) @(vif.drv_cb);
      `uvm_info("DRV", {"start ", req.convert2string()}, UVM_HIGH)
      fork begin
        fork
          begin
            if (req.kind == AXI_WRITE) drive_write(req);
            else                       drive_read(req);
          end
          begin
            @(negedge vif.aresetn);
            `uvm_warning("DRV", "reset asserted during a transaction; aborted")
            req.resp = AXI_SLVERR;
          end
        join_any
        disable fork;
      end join
      `uvm_info("DRV", {"done  ", req.convert2string()}, UVM_HIGH)
      seq_item_port.item_done();
    end
  endtask

  // ---------------------------------------------------------------------------
  protected task automatic drive_aw(axi_lite_item t);
    int unsigned n = 0;
    repeat (t.aw_delay) @(vif.drv_cb);
    vif.drv_cb.awaddr  <= t.addr;
    vif.drv_cb.awprot  <= t.prot;
    vif.drv_cb.awvalid <= 1'b1;
    do begin
      @(vif.drv_cb);
      if (++n > cfg.handshake_timeout) `uvm_fatal("DRV", "AWREADY timeout")
    end while (vif.drv_cb.awready !== 1'b1);
    vif.drv_cb.awvalid <= 1'b0;
    if (cfg.rand_idle_payload) vif.drv_cb.awaddr <= $urandom;
  endtask

  protected task automatic drive_w(axi_lite_item t);
    int unsigned n = 0;
    repeat (t.w_delay) @(vif.drv_cb);
    vif.drv_cb.wdata  <= t.data;
    vif.drv_cb.wstrb  <= t.strb;
    vif.drv_cb.wvalid <= 1'b1;
    do begin
      @(vif.drv_cb);
      if (++n > cfg.handshake_timeout) `uvm_fatal("DRV", "WREADY timeout")
    end while (vif.drv_cb.wready !== 1'b1);
    vif.drv_cb.wvalid <= 1'b0;
    if (cfg.rand_idle_payload) begin
      vif.drv_cb.wdata <= $urandom;
      vif.drv_cb.wstrb <= 4'($urandom);
    end
  endtask

  protected task automatic drive_write(axi_lite_item t);
    int unsigned n = 0;
    fork
      drive_aw(t);
      drive_w(t);
    join
    repeat (t.bready_delay) @(vif.drv_cb);
    vif.drv_cb.bready <= 1'b1;
    do begin
      @(vif.drv_cb);
      if (++n > cfg.handshake_timeout) `uvm_fatal("DRV", "BVALID timeout")
    end while (vif.drv_cb.bvalid !== 1'b1);
    t.resp = axi_lite_resp_e'(vif.drv_cb.bresp);
    vif.drv_cb.bready <= 1'b0;
  endtask

  protected task automatic drive_read(axi_lite_item t);
    int unsigned n = 0;
    repeat (t.ar_delay) @(vif.drv_cb);
    vif.drv_cb.araddr  <= t.addr;
    vif.drv_cb.arprot  <= t.prot;
    vif.drv_cb.arvalid <= 1'b1;
    do begin
      @(vif.drv_cb);
      if (++n > cfg.handshake_timeout) `uvm_fatal("DRV", "ARREADY timeout")
    end while (vif.drv_cb.arready !== 1'b1);
    vif.drv_cb.arvalid <= 1'b0;
    if (cfg.rand_idle_payload) vif.drv_cb.araddr <= $urandom;
    // RREADY may be raised before RVALID arrives
    repeat (t.rready_delay) @(vif.drv_cb);
    vif.drv_cb.rready <= 1'b1;
    n = 0;
    do begin
      @(vif.drv_cb);
      if (++n > cfg.handshake_timeout) `uvm_fatal("DRV", "RVALID timeout")
    end while (vif.drv_cb.rvalid !== 1'b1);
    t.data = vif.drv_cb.rdata;
    t.resp = axi_lite_resp_e'(vif.drv_cb.rresp);
    vif.drv_cb.rready <= 1'b0;
  endtask

endclass
// ---- end agents/axi_lite/axi_lite_driver.svh ----

// ---- begin agents/axi_lite/axi_lite_monitor.svh ----
// axi_lite_monitor.svh - passive AXI4-Lite monitor
//
// Samples every channel through mon_cb, pairs AW/W/B (writes) and AR/R
// (reads) in order (AXI4-Lite has no IDs, responses are in order per
// direction) and publishes each completed transaction on `ap` with the
// handshake timestamps used by the scoreboard.
class axi_lite_monitor extends uvm_monitor;
  `uvm_component_utils(axi_lite_monitor)

  axi_lite_cfg        cfg;
  virtual axi_lite_if vif;

  uvm_analysis_port #(axi_lite_item) ap;

  typedef struct {
    bit [31:0]   addr;
    bit [2:0]    prot;
    realtime     t;
    int unsigned wait_cyc;
  } addr_beat_t;

  typedef struct {
    bit [31:0]   data;
    bit [3:0]    strb;
    realtime     t;
    int unsigned wait_cyc;
  } data_beat_t;

  protected addr_beat_t aw_q[$], ar_q[$];
  protected data_beat_t w_q[$];
  protected int unsigned aw_wait, w_wait, ar_wait, b_wait, r_wait;
  protected int unsigned wr_idle, rd_idle;
  int unsigned n_wr, n_rd;

  function new(string name, uvm_component parent);
    super.new(name, parent);
    ap = new("ap", this);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (cfg == null) `uvm_fatal("CFG", "axi_lite_monitor: cfg not set")
    vif = cfg.vif;
  endfunction

  task run_phase(uvm_phase phase);
    forever begin
      @(vif.mon_cb);
      if (vif.aresetn !== 1'b1) begin
        aw_q.delete(); w_q.delete(); ar_q.delete();
        aw_wait = 0; w_wait = 0; ar_wait = 0; b_wait = 0; r_wait = 0;
        wr_idle = 0; rd_idle = 0;
        continue;
      end
      sample_cycle();
    end
  endtask

  protected function void sample_cycle();
    realtime now = $realtime;
    bit wr_busy, rd_busy;

    // ---------------- request channels ----------------
    if (vif.mon_cb.awvalid === 1'b1) begin
      if (vif.mon_cb.awready === 1'b1) begin
        addr_beat_t b;
        b.addr = vif.mon_cb.awaddr; b.prot = vif.mon_cb.awprot; b.t = now; b.wait_cyc = aw_wait;
        aw_q.push_back(b);
        aw_wait = 0;
      end else aw_wait++;
    end
    if (vif.mon_cb.wvalid === 1'b1) begin
      if (vif.mon_cb.wready === 1'b1) begin
        data_beat_t d;
        d.data = vif.mon_cb.wdata; d.strb = vif.mon_cb.wstrb; d.t = now; d.wait_cyc = w_wait;
        w_q.push_back(d);
        w_wait = 0;
      end else w_wait++;
    end
    if (vif.mon_cb.arvalid === 1'b1) begin
      if (vif.mon_cb.arready === 1'b1) begin
        addr_beat_t b;
        b.addr = vif.mon_cb.araddr; b.prot = vif.mon_cb.arprot; b.t = now; b.wait_cyc = ar_wait;
        ar_q.push_back(b);
        ar_wait = 0;
      end else ar_wait++;
    end

    // ---------------- write response ----------------
    if (vif.mon_cb.bvalid === 1'b1) begin
      if (vif.mon_cb.bready === 1'b1) begin
        if (aw_q.size() == 0 || w_q.size() == 0) begin
          `uvm_error("MON", "write response without matching AW/W handshake")
        end else begin
          axi_lite_item t = axi_lite_item::type_id::create("wr_tr");
          addr_beat_t a = aw_q.pop_front();
          data_beat_t d = w_q.pop_front();
          t.kind      = AXI_WRITE;
          t.addr      = a.addr;
          t.prot      = a.prot;
          t.data      = d.data;
          t.strb      = d.strb;
          t.resp      = axi_lite_resp_e'(vif.mon_cb.bresp);
          t.t_req     = (a.t < d.t) ? a.t : d.t;
          t.t_exec    = (a.t > d.t) ? a.t : d.t;
          t.t_resp    = now;
          t.req_wait  = a.wait_cyc + d.wait_cyc;
          t.resp_wait = b_wait;
          t.gap       = wr_idle;
          wr_idle     = 0;
          n_wr++;
          `uvm_info("MON", t.convert2string(), UVM_HIGH)
          ap.write(t);
        end
        b_wait = 0;
      end else b_wait++;
    end

    // ---------------- read response ----------------
    if (vif.mon_cb.rvalid === 1'b1) begin
      if (vif.mon_cb.rready === 1'b1) begin
        if (ar_q.size() == 0) begin
          `uvm_error("MON", "read response without matching AR handshake")
        end else begin
          axi_lite_item t = axi_lite_item::type_id::create("rd_tr");
          addr_beat_t a = ar_q.pop_front();
          t.kind      = AXI_READ;
          t.addr      = a.addr;
          t.prot      = a.prot;
          t.data      = vif.mon_cb.rdata;
          t.strb      = 4'hF;
          t.resp      = axi_lite_resp_e'(vif.mon_cb.rresp);
          t.t_req     = a.t;
          t.t_exec    = a.t;
          t.t_resp    = now;
          t.req_wait  = a.wait_cyc;
          t.resp_wait = r_wait;
          t.gap       = rd_idle;
          rd_idle     = 0;
          n_rd++;
          `uvm_info("MON", t.convert2string(), UVM_HIGH)
          ap.write(t);
        end
        r_wait = 0;
      end else r_wait++;
    end

    // Idle-cycle counters used for back-to-back coverage
    wr_busy = (vif.mon_cb.awvalid === 1'b1) || (vif.mon_cb.wvalid === 1'b1) ||
              (vif.mon_cb.bvalid === 1'b1) || aw_q.size() != 0 || w_q.size() != 0;
    rd_busy = (vif.mon_cb.arvalid === 1'b1) || (vif.mon_cb.rvalid === 1'b1) || ar_q.size() != 0;
    if (!wr_busy) wr_idle++;
    if (!rd_busy) rd_idle++;
  endfunction

  function void report_phase(uvm_phase phase);
    `uvm_info("MON", $sformatf("observed %0d writes, %0d reads", n_wr, n_rd), UVM_LOW)
  endfunction

endclass
// ---- end agents/axi_lite/axi_lite_monitor.svh ----

// ---- begin agents/axi_lite/axi_lite_coverage.svh ----
// axi_lite_coverage.svh - protocol-level functional coverage (DUT independent)
class axi_lite_coverage extends uvm_subscriber #(axi_lite_item);
  `uvm_component_utils(axi_lite_coverage)

  axi_lite_item tr;

  covergroup cg_xfer;
    option.per_instance = 1;
    cp_kind: coverpoint tr.kind;
    cp_resp: coverpoint tr.resp {
      bins okay   = {AXI_OKAY};
      bins slverr = {AXI_SLVERR};
      bins decerr = {AXI_DECERR};
      illegal_bins exokay = {AXI_EXOKAY};
    }
    cp_strb: coverpoint tr.strb iff (tr.kind == AXI_WRITE) {
      bins full    = {4'hF};
      bins none    = {4'h0};
      bins single[] = {4'h1, 4'h2, 4'h4, 4'h8};
      bins half[]   = {4'h3, 4'hC};
      bins other   = default;
    }
    cp_req_wait: coverpoint tr.req_wait {
      bins zero = {0};
      bins short_wait = {[1:3]};
      bins long_wait  = {[4:$]};
    }
    cp_resp_wait: coverpoint tr.resp_wait {
      bins zero = {0};
      bins short_wait = {[1:3]};
      bins long_wait  = {[4:$]};
    }
    cp_gap: coverpoint tr.gap {
      bins back_to_back = {0};
      bins short_gap    = {[1:4]};
      bins long_gap     = {[5:$]};
    }
    cp_aw_w_order: coverpoint ((tr.t_req == tr.t_exec) ? 0 : 1) iff (tr.kind == AXI_WRITE) {
      bins same_cycle = {0};
      bins split      = {1};
    }
    x_kind_resp:  cross cp_kind, cp_resp;
    x_kind_gap:   cross cp_kind, cp_gap;
    x_kind_rwait: cross cp_kind, cp_resp_wait;
  endgroup

  function new(string name, uvm_component parent);
    super.new(name, parent);
    cg_xfer = new();
  endfunction

  function void write(axi_lite_item t);
    tr = t;
    cg_xfer.sample();
  endfunction

  function void report_phase(uvm_phase phase);
    `uvm_info("COV", $sformatf("AXI4-Lite transfer coverage: %0.2f%%", cg_xfer.get_inst_coverage()), UVM_LOW)
  endfunction

endclass
// ---- end agents/axi_lite/axi_lite_coverage.svh ----

// ---- begin agents/axi_lite/axi_lite_agent.svh ----
// axi_lite_agent.svh - AXI4-Lite master agent
class axi_lite_agent extends uvm_agent;
  `uvm_component_utils(axi_lite_agent)

  axi_lite_cfg        cfg;
  axi_lite_sequencer  sqr;
  axi_lite_driver     drv;
  axi_lite_monitor    mon;
  axi_lite_coverage   cov;

  uvm_analysis_port #(axi_lite_item) ap;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (cfg == null && !uvm_config_db#(axi_lite_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("CFG", "axi_lite_agent: no axi_lite_cfg")
    if (cfg.vif == null && !uvm_config_db#(virtual axi_lite_if)::get(this, "", "vif", cfg.vif))
      `uvm_fatal("CFG", "axi_lite_agent: no virtual axi_lite_if")
    mon = axi_lite_monitor::type_id::create("mon", this);
    mon.cfg = cfg;
    if (cfg.is_active == UVM_ACTIVE) begin
      sqr = axi_lite_sequencer::type_id::create("sqr", this);
      drv = axi_lite_driver::type_id::create("drv", this);
      sqr.cfg = cfg;
      drv.cfg = cfg;
    end
    if (cfg.has_coverage) cov = axi_lite_coverage::type_id::create("cov", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    ap = mon.ap;
    if (cfg.is_active == UVM_ACTIVE) drv.seq_item_port.connect(sqr.seq_item_export);
    if (cfg.has_coverage) mon.ap.connect(cov.analysis_export);
  endfunction

endclass
// ---- end agents/axi_lite/axi_lite_agent.svh ----

// ---- begin agents/axi_lite/axi_lite_reg_adapter.svh ----
// axi_lite_reg_adapter.svh - uvm_reg frontdoor through the AXI4-Lite agent
//
// The driver writes the response back into the request item, so
// provides_responses = 0 and bus2reg() reads the completed item.
// Any non-OKAY response maps to UVM_NOT_OK (the predictor then leaves the
// mirror unchanged, matching a slave that ignores an erroring access).
class axi_lite_reg_adapter extends uvm_reg_adapter;
  `uvm_object_utils(axi_lite_reg_adapter)

  // Delay profile applied to register accesses (random by default so RAL
  // traffic also exercises back-pressure).
  axi_lite_dly_e dly_mode = AXI_DLY_RANDOM;

  function new(string name = "axi_lite_reg_adapter");
    super.new(name);
    supports_byte_enable = 1;
    provides_responses   = 0;
  endfunction

  virtual function uvm_sequence_item reg2bus(const ref uvm_reg_bus_op rw);
    axi_lite_item   t  = axi_lite_item::type_id::create("reg_tr");
    axi_lite_kind_e k  = (rw.kind == UVM_WRITE) ? AXI_WRITE : AXI_READ;
    bit [31:0]      a  = rw.addr[31:0];
    axi_lite_dly_e  dm = dly_mode;
    if (!t.randomize() with { kind == k; addr == a; dly_mode == dm; })
      `uvm_fatal("ADAPT", "randomize failed")
    t.data = rw.data[31:0];
    t.strb = (rw.kind == UVM_WRITE) ? rw.byte_en[3:0] : 4'hF;
    return t;
  endfunction

  virtual function void bus2reg(uvm_sequence_item bus_item, ref uvm_reg_bus_op rw);
    axi_lite_item t;
    if (!$cast(t, bus_item)) begin
      `uvm_fatal("ADAPT", "bus2reg: not an axi_lite_item")
      return;
    end
    rw.kind    = (t.kind == AXI_WRITE) ? UVM_WRITE : UVM_READ;
    rw.addr    = t.addr;
    rw.data    = t.data;
    rw.byte_en = t.strb;
    rw.n_bits  = 32;
    rw.status  = (t.resp == AXI_OKAY) ? UVM_IS_OK : UVM_NOT_OK;
  endfunction

endclass
// ---- end agents/axi_lite/axi_lite_reg_adapter.svh ----

// ---- begin agents/axi_lite/axi_lite_seq_lib.svh ----
// axi_lite_seq_lib.svh - AXI4-Lite sequence library
//
//   axi_lite_base_seq        write()/read() helpers
//   axi_lite_single_write_seq / axi_lite_single_read_seq
//   axi_lite_b2b_seq         back-to-back writes, reads or alternating, no idle
//   axi_lite_rand_seq        random kind/address/data/strobe with random delays
//   axi_lite_err_seq         accesses expected to return SLVERR/DECERR
//
// Address selection is DUT independent: sequences take explicit address
// lists/ranges from the caller.

class axi_lite_base_seq extends uvm_sequence #(axi_lite_item);
  `uvm_object_utils(axi_lite_base_seq)

  axi_lite_dly_e dly_mode = AXI_DLY_RANDOM;

  function new(string name = "axi_lite_base_seq");
    super.new(name);
  endfunction

  task write(input bit [31:0] addr, input bit [31:0] data,
             output axi_lite_resp_e resp, input bit [3:0] strb = 4'hF);
    axi_lite_item t = axi_lite_item::type_id::create("wr");
    start_item(t);
    if (!t.randomize() with { kind == AXI_WRITE; addr == local::addr; data == local::data;
                              strb == local::strb; dly_mode == local::dly_mode; })
      `uvm_fatal("SEQ", "randomize failed")
    finish_item(t);
    resp = t.resp;
  endtask

  task read(input bit [31:0] addr, output bit [31:0] data, output axi_lite_resp_e resp);
    axi_lite_item t = axi_lite_item::type_id::create("rd");
    start_item(t);
    if (!t.randomize() with { kind == AXI_READ; addr == local::addr; dly_mode == local::dly_mode; })
      `uvm_fatal("SEQ", "randomize failed")
    finish_item(t);
    data = t.data;
    resp = t.resp;
  endtask

endclass

// -----------------------------------------------------------------------------
class axi_lite_single_write_seq extends axi_lite_base_seq;
  `uvm_object_utils(axi_lite_single_write_seq)
  rand bit [31:0] addr;
  rand bit [31:0] data;
  rand bit [3:0]  strb;
  axi_lite_resp_e resp;
  constraint c_addr { addr[1:0] == 0; soft strb == 4'hF; }
  function new(string name = "axi_lite_single_write_seq"); super.new(name); endfunction
  task body();
    write(addr, data, resp, strb);
  endtask
endclass

class axi_lite_single_read_seq extends axi_lite_base_seq;
  `uvm_object_utils(axi_lite_single_read_seq)
  rand bit [31:0] addr;
  bit [31:0]      data;
  axi_lite_resp_e resp;
  constraint c_addr { addr[1:0] == 0; }
  function new(string name = "axi_lite_single_read_seq"); super.new(name); endfunction
  task body();
    read(addr, data, resp);
  endtask
endclass

// -----------------------------------------------------------------------------
// Back-to-back: zero delays on every channel, no idle cycles between items.
class axi_lite_b2b_seq extends axi_lite_base_seq;
  `uvm_object_utils(axi_lite_b2b_seq)

  typedef enum { B2B_WRITES, B2B_READS, B2B_ALTERNATE, B2B_WR_THEN_RD } b2b_mode_e;
  rand b2b_mode_e   mode;
  rand int unsigned n;
  bit [31:0]        addrs[$];       // cycled through; must be supplied
  constraint c_n { n inside {[2:16]}; }

  function new(string name = "axi_lite_b2b_seq");
    super.new(name);
    dly_mode = AXI_DLY_ZERO;
  endfunction

  task body();
    axi_lite_resp_e r;
    bit [31:0] d;
    if (addrs.size() == 0) `uvm_fatal("SEQ", "axi_lite_b2b_seq: no addresses")
    for (int i = 0; i < n; i++) begin
      bit [31:0] a = addrs[i % addrs.size()];
      case (mode)
        B2B_WRITES:    write(a, $urandom, r);
        B2B_READS:     read(a, d, r);
        B2B_ALTERNATE: if (i % 2) read(a, d, r); else write(a, $urandom, r);
        B2B_WR_THEN_RD: begin write(a, $urandom, r); read(a, d, r); end
      endcase
    end
  endtask
endclass

// -----------------------------------------------------------------------------
// Random traffic over caller-supplied address ranges.
class axi_lite_rand_seq extends axi_lite_base_seq;
  `uvm_object_utils(axi_lite_rand_seq)

  rand int unsigned n;
  int unsigned      wr_pct = 50;
  bit               partial_strb = 1;   // allow byte strobes other than 4'hF
  bit [31:0]        lo[$];              // inclusive range bounds
  bit [31:0]        hi[$];
  constraint c_n { n inside {[10:50]}; }

  function new(string name = "axi_lite_rand_seq");
    super.new(name);
  endfunction

  function void add_range(bit [31:0] l, bit [31:0] h);
    lo.push_back(l);
    hi.push_back(h);
  endfunction

  task body();
    if (lo.size() == 0) add_range(32'h0, 32'hFFFF_FFFC);
    for (int i = 0; i < n; i++) begin
      axi_lite_item t = axi_lite_item::type_id::create("rnd");
      int unsigned  k = $urandom_range(lo.size() - 1);
      bit [31:0]    a = (lo[k] + ($urandom_range((hi[k] - lo[k]) / 4) * 4));
      bit           w = ($urandom_range(99) < wr_pct);
      start_item(t);
      if (!t.randomize() with { addr == a;
                                kind == (w ? AXI_WRITE : AXI_READ);
                                dly_mode == local::dly_mode;
                                (!local::partial_strb) -> strb == 4'hF; })
        `uvm_fatal("SEQ", "randomize failed")
      finish_item(t);
    end
  endtask
endclass

// -----------------------------------------------------------------------------
// Error-response sequence: issues reads/writes to caller-supplied addresses
// that are expected to fail and counts responses. Checking whether a given
// response is correct is the scoreboard's job; this sequence only reports
// what it saw so tests can assert that errors were really provoked.
class axi_lite_err_seq extends axi_lite_base_seq;
  `uvm_object_utils(axi_lite_err_seq)

  bit [31:0]   addrs[$];
  int unsigned reps = 1;
  int unsigned n_okay, n_slverr, n_decerr;

  function new(string name = "axi_lite_err_seq");
    super.new(name);
  endfunction

  task body();
    axi_lite_resp_e r;
    bit [31:0] d;
    foreach (addrs[i]) begin
      repeat (reps) begin
        if ($urandom_range(1)) write(addrs[i], $urandom, r);
        else                   read(addrs[i], d, r);
        case (r)
          AXI_OKAY:   n_okay++;
          AXI_SLVERR: n_slverr++;
          AXI_DECERR: n_decerr++;
          default: ;
        endcase
      end
    end
    `uvm_info("ERRSEQ", $sformatf("responses: OKAY=%0d SLVERR=%0d DECERR=%0d",
                                  n_okay, n_slverr, n_decerr), UVM_MEDIUM)
  endtask
endclass
// ---- end agents/axi_lite/axi_lite_seq_lib.svh ----

endpackage
// ---- end agents/axi_lite/axi_lite_pkg.sv ----

// ---- begin agents/pwr/pwr_pkg.sv ----
// -----------------------------------------------------------------------------
// pwr_pkg.sv - reusable power-domain agent (UVM, IEEE 1800.2)
//
//   pwr_cfg        switch latencies, CPU model options, domain-output noise
//   pwr_item       stimulus: WFI, wake IRQ, raw IRQ levels, domain outputs, wait
//   pwr_obs        monitor snapshot of every pin (published on any change)
//   pwr_driver     reactive power-switch + CPU model, executes pwr_items
//   pwr_monitor    passive, publishes pwr_obs on change
//   pwr_coverage   pin-level edge coverage
//   pwr_agent
//   sequences      wfi, wake, irq noise, domain-output stimulus
//
// The agent knows nothing about a particular PMU's sequencing rules; those
// live in the environment's reference model.
// -----------------------------------------------------------------------------

package pwr_pkg;

  import uvm_pkg::*;
  `include "uvm_macros.svh"

  localparam int IRQ_W = `PWR_IRQ_W;
  localparam int ISO_W = `PWR_ISO_W;

  typedef enum {
    PWR_WFI,        // CPU executes WFI (waits until the domain is running)
    PWR_WAKE,       // assert wake IRQ(s), held until the CPU is running again
    PWR_IRQ_SET,    // raw IRQ level set (no auto-clear)
    PWR_IRQ_CLR,    // raw IRQ level clear
    PWR_DOM_OUT,    // drive raw domain outputs
    PWR_WAIT        // idle for N cycles
  } pwr_op_e;


// ---- begin agents/pwr/pwr_cfg.svh ----
// pwr_cfg.svh - power agent configuration
class pwr_cfg extends uvm_object;

  virtual pwr_if vif;

  uvm_active_passive_enum is_active = UVM_ACTIVE;
  bit has_coverage = 1;

  // Power-switch model: power_good rises pgood_on_{min,max} cycles after the
  // switch is enabled and falls pgood_off_{min,max} cycles after it is
  // disabled (randomised per event).
  int unsigned pgood_on_min  = 2;
  int unsigned pgood_on_max  = 12;
  int unsigned pgood_off_min = 0;
  int unsigned pgood_off_max = 3;

  // CPU model: cycles after the domain clock restarts before WFI drops.
  int unsigned wfi_exit_delay = 0;

  // Wake IRQs raised by PWR_WAKE are cleared this many cycles after the
  // domain is running again (models the CPU servicing the interrupt).
  int unsigned irq_clear_min = 1;
  int unsigned irq_clear_max = 6;

  // Drive random values on the raw domain outputs while the domain is not
  // running (models undefined outputs of an off/reset domain), and toggle
  // them randomly while it runs.
  bit rand_dom_out = 1;

  `uvm_object_utils_begin(pwr_cfg)
    `uvm_field_enum(uvm_active_passive_enum, is_active, UVM_DEFAULT)
    `uvm_field_int(has_coverage, UVM_DEFAULT)
    `uvm_field_int(pgood_on_min, UVM_DEFAULT | UVM_DEC)
    `uvm_field_int(pgood_on_max, UVM_DEFAULT | UVM_DEC)
    `uvm_field_int(pgood_off_min, UVM_DEFAULT | UVM_DEC)
    `uvm_field_int(pgood_off_max, UVM_DEFAULT | UVM_DEC)
    `uvm_field_int(wfi_exit_delay, UVM_DEFAULT | UVM_DEC)
    `uvm_field_int(rand_dom_out, UVM_DEFAULT)
  `uvm_object_utils_end

  function new(string name = "pwr_cfg");
    super.new(name);
  endfunction

endclass
// ---- end agents/pwr/pwr_cfg.svh ----

// ---- begin agents/pwr/pwr_item.svh ----
// pwr_item.svh - power agent stimulus item
class pwr_item extends uvm_sequence_item;

  rand pwr_op_e          op;
  rand bit [IRQ_W-1:0]   irq;      // PWR_WAKE / PWR_IRQ_SET / PWR_IRQ_CLR
  rand bit [ISO_W-1:0]   dom_out;  // PWR_DOM_OUT
  rand int unsigned      cycles;   // PWR_WAIT, or delay before the action
  bit                    timed_out;

  constraint c_cycles { cycles <= 200; soft cycles <= 20; }
  constraint c_wake   { op == PWR_WAKE -> irq != 0; }

  `uvm_object_utils_begin(pwr_item)
    `uvm_field_enum(pwr_op_e, op, UVM_DEFAULT)
    `uvm_field_int(irq, UVM_DEFAULT)
    `uvm_field_int(dom_out, UVM_DEFAULT)
    `uvm_field_int(cycles, UVM_DEFAULT | UVM_DEC)
  `uvm_object_utils_end

  function new(string name = "pwr_item");
    super.new(name);
  endfunction

  function string convert2string();
    return $sformatf("%s irq=0x%0h dom_out=0x%0h cycles=%0d", op.name(), irq, dom_out, cycles);
  endfunction

endclass
// ---- end agents/pwr/pwr_item.svh ----

// ---- begin agents/pwr/pwr_obs.svh ----
// pwr_obs.svh - snapshot of all power-interface pins at one clock edge
class pwr_obs extends uvm_sequence_item;

  realtime          t;
  longint unsigned  cycle;
  bit               rst_n;
  bit               clk_en, iso_en, ret_en, pwr_en, dom_rst_n, pwr_good, wfi;
  bit [1:0]         dvfs_sel;
  bit [IRQ_W-1:0]   wake_irq;
  bit [ISO_W-1:0]   dom_out, dom_out_iso;
  bit               has_x;   // any monitored pin was X/Z

  `uvm_object_utils(pwr_obs)

  function new(string name = "pwr_obs");
    super.new(name);
  endfunction

  // Compact vector of the PMU control outputs, for change detection
  function bit [7:0] ctrl_vec();
    return {dvfs_sel, clk_en, iso_en, ret_en, pwr_en, dom_rst_n, pwr_good};
  endfunction

  function bit same_as(pwr_obs o);
    return (o != null) && rst_n == o.rst_n && ctrl_vec() == o.ctrl_vec() && wfi == o.wfi &&
           wake_irq == o.wake_irq && dom_out == o.dom_out && dom_out_iso == o.dom_out_iso &&
           has_x == o.has_x;
  endfunction

  function string convert2string();
    return $sformatf("@%0t cyc=%0d rst_n=%0b clk_en=%0b iso=%0b ret=%0b pwr_en=%0b pgood=%0b dom_rst_n=%0b dvfs=%0d wfi=%0b irq=0x%0h out=0x%0h iso_out=0x%0h%s",
                     t, cycle, rst_n, clk_en, iso_en, ret_en, pwr_en, pwr_good, dom_rst_n, dvfs_sel,
                     wfi, wake_irq, dom_out, dom_out_iso, has_x ? " X!" : "");
  endfunction

endclass
// ---- end agents/pwr/pwr_obs.svh ----

// ---- begin agents/pwr/pwr_sequencer.svh ----
// pwr_sequencer.svh
class pwr_sequencer extends uvm_sequencer #(pwr_item);
  `uvm_component_utils(pwr_sequencer)

  pwr_cfg cfg;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction
endclass
// ---- end agents/pwr/pwr_sequencer.svh ----

// ---- begin agents/pwr/pwr_driver.svh ----
// pwr_driver.svh - reactive model of the power switch, the CPU and the wake
// sources around a switchable domain.
//
// A single per-cycle loop owns every driven pin:
//   * power switch : power_good follows the switch enable with a random
//                    latency (cfg.pgood_on_*/pgood_off_*)
//   * CPU          : raises WFI on request once the domain is running, drops
//                    it when the domain clock restarts or the domain is reset
//   * wake IRQs    : PWR_WAKE bits are held until the CPU runs again and are
//                    then cleared after a random service time
//   * domain outs  : random garbage while the domain is not running
// Sequence items only post requests into this model.
class pwr_driver extends uvm_driver #(pwr_item);
  `uvm_component_utils(pwr_driver)

  pwr_cfg        cfg;
  virtual pwr_if vif;

  // model state
  protected bit             pg_val, pg_tgt;
  protected int unsigned    pg_cnt;
  protected bit             wfi_val, wfi_req;
  protected int             wfi_drop_cnt;
  protected bit             clk_en_q;
  protected bit [IRQ_W-1:0] irq_level, irq_auto;
  protected int             irq_clr_cnt;
  protected bit [ISO_W-1:0] dom_val;
  protected event           wfi_taken;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (cfg == null) `uvm_fatal("CFG", "pwr_driver: cfg not set")
    vif = cfg.vif;
  endfunction

  task run_phase(uvm_phase phase);
    vif.drive_reset();
    fork
      model_loop();
      item_loop();
    join
  endtask

  // ---------------------------------------------------------------------------
  protected function void reset_model();
    pg_val = 0; pg_tgt = 0; pg_cnt = 0;
    wfi_val = 0; wfi_req = 0; wfi_drop_cnt = -1; clk_en_q = 0;
    irq_level = '0; irq_auto = '0; irq_clr_cnt = -1;
    dom_val = '0;
  endfunction

  protected task model_loop();
    reset_model();
    forever begin
      @(vif.drv_cb);
      if (vif.rst_n !== 1'b1) begin
        reset_model();
        vif.drv_cb.pwr_good <= 1'b0;
        vif.drv_cb.wfi      <= 1'b0;
        vif.drv_cb.wake_irq <= '0;
        vif.drv_cb.dom_out  <= '0;
        continue;
      end
      step_model();
    end
  endtask

  protected function void step_model();
    bit pwr_en    = (vif.drv_cb.pwr_en    === 1'b1);
    bit clk_en    = (vif.drv_cb.clk_en    === 1'b1);
    bit iso_en    = (vif.drv_cb.iso_en    !== 1'b0);
    bit dom_rst_n = (vif.drv_cb.dom_rst_n === 1'b1);
    bit running;

    // ---------------- power switch ----------------
    if (pwr_en != pg_tgt) begin
      pg_tgt = pwr_en;
      pg_cnt = pwr_en ? $urandom_range(cfg.pgood_on_max,  cfg.pgood_on_min)
                      : $urandom_range(cfg.pgood_off_max, cfg.pgood_off_min);
    end
    if (pg_val != pg_tgt) begin
      if (pg_cnt == 0) pg_val = pg_tgt;
      else             pg_cnt--;
    end

    running = clk_en && !iso_en && dom_rst_n && pg_val;

    // ---------------- CPU: WFI ----------------
    if (!dom_rst_n || !pg_val) begin
      wfi_val = 0;
      wfi_drop_cnt = -1;
    end else begin
      if (wfi_val && clk_en && !clk_en_q) wfi_drop_cnt = cfg.wfi_exit_delay;
      if (wfi_drop_cnt == 0) begin wfi_val = 0; wfi_drop_cnt = -1; end
      else if (wfi_drop_cnt > 0) wfi_drop_cnt--;
      if (wfi_req && running && !wfi_val) begin
        wfi_val = 1;
        wfi_req = 0;
        -> wfi_taken;
      end
    end
    clk_en_q = clk_en;

    // ---------------- wake IRQs ----------------
    if (irq_auto != 0) begin
      if (running && !wfi_val) begin
        if (irq_clr_cnt < 0) irq_clr_cnt = $urandom_range(cfg.irq_clear_max, cfg.irq_clear_min);
        else if (irq_clr_cnt == 0) begin irq_auto = '0; irq_clr_cnt = -1; end
        else irq_clr_cnt--;
      end else irq_clr_cnt = -1;
    end

    // ---------------- domain outputs ----------------
    if (cfg.rand_dom_out && (!running || ($urandom_range(7) == 0)))
      dom_val = ISO_W'({$urandom, $urandom});

    vif.drv_cb.pwr_good <= pg_val;
    vif.drv_cb.wfi      <= wfi_val;
    vif.drv_cb.wake_irq <= irq_level | irq_auto;
    vif.drv_cb.dom_out  <= dom_val;
  endfunction

  // ---------------------------------------------------------------------------
  protected task item_loop();
    pwr_item req;
    forever begin
      seq_item_port.get_next_item(req);
      `uvm_info("PWRDRV", req.convert2string(), UVM_HIGH)
      if (req.op != PWR_WAIT) repeat (req.cycles) @(vif.drv_cb);
      case (req.op)
        PWR_WFI: begin
          wfi_req = 1;
          fork begin
            fork
              @(wfi_taken);
              begin repeat (100000) @(vif.drv_cb); req.timed_out = 1; wfi_req = 0; end
            join_any
            disable fork;
          end join
          if (req.timed_out) `uvm_error("PWRDRV", "WFI request: domain never reached running state")
        end
        PWR_WAKE:    irq_auto  |= req.irq;
        PWR_IRQ_SET: irq_level |= req.irq;
        PWR_IRQ_CLR: irq_level &= ~req.irq;
        PWR_DOM_OUT: dom_val    = req.dom_out;
        PWR_WAIT:    repeat (req.cycles) @(vif.drv_cb);
        default: ;
      endcase
      seq_item_port.item_done();
    end
  endtask

endclass
// ---- end agents/pwr/pwr_driver.svh ----

// ---- begin agents/pwr/pwr_monitor.svh ----
// pwr_monitor.svh - passive power-interface monitor
//
// Samples every pin through mon_cb on each clock and publishes a pwr_obs
// snapshot whenever anything changed (including reset). Snapshots carry the
// sample time so the scoreboard can correlate them with bus transactions.
class pwr_monitor extends uvm_monitor;
  `uvm_component_utils(pwr_monitor)

  pwr_cfg        cfg;
  virtual pwr_if vif;

  uvm_analysis_port #(pwr_obs) ap;

  pwr_obs          last;
  longint unsigned cycle;
  int unsigned     n_pub;

  function new(string name, uvm_component parent);
    super.new(name, parent);
    ap = new("ap", this);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (cfg == null) `uvm_fatal("CFG", "pwr_monitor: cfg not set")
    vif = cfg.vif;
  endfunction

  task run_phase(uvm_phase phase);
    forever begin
      pwr_obs o;
      @(vif.mon_cb);
      cycle++;
      o = pwr_obs::type_id::create("obs");
      o.t           = $realtime;
      o.cycle       = cycle;
      o.rst_n       = (vif.rst_n === 1'b1);
      o.clk_en      = vif.mon_cb.clk_en;
      o.iso_en      = vif.mon_cb.iso_en;
      o.ret_en      = vif.mon_cb.ret_en;
      o.pwr_en      = vif.mon_cb.pwr_en;
      o.dom_rst_n   = vif.mon_cb.dom_rst_n;
      o.pwr_good    = vif.mon_cb.pwr_good;
      o.wfi         = vif.mon_cb.wfi;
      o.dvfs_sel    = vif.mon_cb.dvfs_sel;
      o.wake_irq    = vif.mon_cb.wake_irq;
      o.dom_out     = vif.mon_cb.dom_out;
      o.dom_out_iso = vif.mon_cb.dom_out_iso;
      o.has_x       = o.rst_n && $isunknown({vif.mon_cb.clk_en, vif.mon_cb.iso_en, vif.mon_cb.ret_en,
                                              vif.mon_cb.pwr_en, vif.mon_cb.dom_rst_n, vif.mon_cb.dvfs_sel,
                                              vif.mon_cb.dom_out_iso});
      if (!o.same_as(last)) begin
        `uvm_info("PWRMON", o.convert2string(), UVM_HIGH)
        ap.write(o);
        n_pub++;
        last = o;
      end
    end
  endtask

  function void report_phase(uvm_phase phase);
    `uvm_info("PWRMON", $sformatf("published %0d snapshots over %0d cycles", n_pub, cycle), UVM_LOW)
  endfunction

endclass
// ---- end agents/pwr/pwr_monitor.svh ----

// ---- begin agents/pwr/pwr_coverage.svh ----
// pwr_coverage.svh - pin-level coverage of the power interface (DUT independent)
class pwr_coverage extends uvm_subscriber #(pwr_obs);
  `uvm_component_utils(pwr_coverage)

  pwr_obs cur, prev;

  covergroup cg_pins;
    option.per_instance = 1;
    cp_clk_en:   coverpoint {prev.clk_en,    cur.clk_en}    { bins rise = {2'b01}; bins fall = {2'b10}; }
    cp_iso_en:   coverpoint {prev.iso_en,    cur.iso_en}    { bins rise = {2'b01}; bins fall = {2'b10}; }
    cp_ret_en:   coverpoint {prev.ret_en,    cur.ret_en}    { bins rise = {2'b01}; bins fall = {2'b10}; }
    cp_pwr_en:   coverpoint {prev.pwr_en,    cur.pwr_en}    { bins rise = {2'b01}; bins fall = {2'b10}; }
    cp_pwr_good: coverpoint {prev.pwr_good,  cur.pwr_good}  { bins rise = {2'b01}; bins fall = {2'b10}; }
    cp_rst_n:    coverpoint {prev.dom_rst_n, cur.dom_rst_n} { bins rise = {2'b01}; bins fall = {2'b10}; }
    cp_wfi:      coverpoint {prev.wfi,       cur.wfi}       { bins rise = {2'b01}; bins fall = {2'b10}; }
    cp_dvfs:     coverpoint cur.dvfs_sel { bins opp[] = {[0:2]}; }
    cp_wake:     coverpoint (cur.wake_irq != 0);
  endgroup

  function new(string name, uvm_component parent);
    super.new(name, parent);
    cg_pins = new();
  endfunction

  function void write(pwr_obs t);
    cur = t;
    if (prev != null && t.rst_n && prev.rst_n) cg_pins.sample();
    prev = t;
  endfunction

  function void report_phase(uvm_phase phase);
    `uvm_info("COV", $sformatf("power pin coverage: %0.2f%%", cg_pins.get_inst_coverage()), UVM_LOW)
  endfunction

endclass
// ---- end agents/pwr/pwr_coverage.svh ----

// ---- begin agents/pwr/pwr_agent.svh ----
// pwr_agent.svh - power-domain agent
class pwr_agent extends uvm_agent;
  `uvm_component_utils(pwr_agent)

  pwr_cfg       cfg;
  pwr_sequencer sqr;
  pwr_driver    drv;
  pwr_monitor   mon;
  pwr_coverage  cov;

  uvm_analysis_port #(pwr_obs) ap;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (cfg == null && !uvm_config_db#(pwr_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("CFG", "pwr_agent: no pwr_cfg")
    if (cfg.vif == null && !uvm_config_db#(virtual pwr_if)::get(this, "", "vif", cfg.vif))
      `uvm_fatal("CFG", "pwr_agent: no virtual pwr_if")
    mon = pwr_monitor::type_id::create("mon", this);
    mon.cfg = cfg;
    if (cfg.is_active == UVM_ACTIVE) begin
      sqr = pwr_sequencer::type_id::create("sqr", this);
      drv = pwr_driver::type_id::create("drv", this);
      sqr.cfg = cfg;
      drv.cfg = cfg;
    end
    if (cfg.has_coverage) cov = pwr_coverage::type_id::create("cov", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    ap = mon.ap;
    if (cfg.is_active == UVM_ACTIVE) drv.seq_item_port.connect(sqr.seq_item_export);
    if (cfg.has_coverage) mon.ap.connect(cov.analysis_export);
  endfunction

endclass
// ---- end agents/pwr/pwr_agent.svh ----

// ---- begin agents/pwr/pwr_seq_lib.svh ----
// pwr_seq_lib.svh - agent-level power stimulus sequences
//
// These are the primitive actions; the PMU-specific power-state transition
// and DVFS sequences are virtual sequences in the environment
// (env/pmu_vseq_lib.svh) that combine them with register programming.

class pwr_base_seq extends uvm_sequence #(pwr_item);
  `uvm_object_utils(pwr_base_seq)
  function new(string name = "pwr_base_seq"); super.new(name); endfunction

  task do_op(pwr_op_e op, bit [IRQ_W-1:0] irq = '0, int unsigned cycles = 0,
             bit [ISO_W-1:0] dom_out = '0);
    pwr_item t = pwr_item::type_id::create("t");
    start_item(t);
    if (!t.randomize() with { op == local::op; cycles == local::cycles; })
      `uvm_fatal("SEQ", "randomize failed")
    t.irq     = irq;
    t.dom_out = dom_out;
    finish_item(t);
  endtask
endclass

// CPU executes WFI once the domain is running.
class pwr_wfi_seq extends pwr_base_seq;
  `uvm_object_utils(pwr_wfi_seq)
  rand int unsigned delay;
  constraint c_d { delay <= 8; }
  function new(string name = "pwr_wfi_seq"); super.new(name); endfunction
  task body(); do_op(PWR_WFI, '0, delay); endtask
endclass

// Raise wake interrupt(s); they stay asserted until the CPU runs again.
class pwr_wake_seq extends pwr_base_seq;
  `uvm_object_utils(pwr_wake_seq)
  rand bit [IRQ_W-1:0] irq;
  rand int unsigned    delay;
  constraint c_irq { irq != 0; soft $countones(irq) <= 2; delay <= 8; }
  function new(string name = "pwr_wake_seq"); super.new(name); endfunction
  task body(); do_op(PWR_WAKE, irq, delay); endtask
endclass

// Short pulses on IRQ lines (e.g. masked sources that must NOT wake).
class pwr_irq_pulse_seq extends pwr_base_seq;
  `uvm_object_utils(pwr_irq_pulse_seq)
  rand bit [IRQ_W-1:0] irq;
  rand int unsigned    width;
  constraint c_w { width inside {[1:10]}; }
  function new(string name = "pwr_irq_pulse_seq"); super.new(name); endfunction
  task body();
    do_op(PWR_IRQ_SET, irq);
    do_op(PWR_WAIT, '0, width);
    do_op(PWR_IRQ_CLR, irq);
  endtask
endclass

// Drive a pattern on the raw domain outputs.
class pwr_dom_out_seq extends pwr_base_seq;
  `uvm_object_utils(pwr_dom_out_seq)
  rand bit [ISO_W-1:0] val;
  function new(string name = "pwr_dom_out_seq"); super.new(name); endfunction
  task body(); do_op(PWR_DOM_OUT, '0, 0, val); endtask
endclass

class pwr_wait_seq extends pwr_base_seq;
  `uvm_object_utils(pwr_wait_seq)
  rand int unsigned cycles;
  constraint c_c { cycles inside {[1:50]}; }
  function new(string name = "pwr_wait_seq"); super.new(name); endfunction
  task body(); do_op(PWR_WAIT, '0, cycles); endtask
endclass
// ---- end agents/pwr/pwr_seq_lib.svh ----

endpackage
// ---- end agents/pwr/pwr_pkg.sv ----

// ---- begin ral/pmu_ral_pkg.sv ----
// -----------------------------------------------------------------------------
// pmu_ral_pkg.sv - UVM register model of the PMU
//
// This is the only file that encodes the PMU register map. It matches the stub
// in verif/uvm/stub/pmu_stub.sv (SPEC.md does not define a map). When the real
// PMU is swapped in, regenerate/edit this file; the agents, scoreboard and
// tests reach registers only through this model.
//
//   0x000 ID          RO   PMU identification
//   0x004 CTRL        RW   [0] PD_EN  : WFI powers PD_CPU off (else IDLE)
//                          [1] RET_EN : power-off uses RAM retention (DEEP_SLEEP)
//   0x008 STATUS      RO   [2:0] STATE  [4] CLK_EN [5] ISO_EN [6] RET_EN
//                          [7] PWR_EN [8] PWR_GOOD [9] CPU_RST_N
//                          [13:12] DVFS_CUR [16] DVFS_PEND   (all volatile)
//   0x00C DVFS        RW   [1:0] OPP target (3 = reserved -> SLVERR)
//   0x010 WAKE_MASK   RW   [7:0] wake source enables
//   0x014 WAKE_CAUSE  W1C  [7:0] wake sources that caused the last wake-ups
//   0x018 SEQ_DELAY   RW   [7:0] cycles between sequencing steps
//   0x01C PD_COUNT    RO   [15:0] completed power-down count (volatile)
//   0x100 CPU_WIN.SCRATCH[0..3]  RW, physically in PD_CPU:
//                          SLVERR unless PD_CPU is RUNning, reset on power-off
// -----------------------------------------------------------------------------
package pmu_ral_pkg;

  import uvm_pkg::*;
  `include "uvm_macros.svh"

  // STATUS.STATE encoding
  typedef enum bit [2:0] {
    PMU_ST_RUN   = 3'd0,
    PMU_ST_IDLE  = 3'd1,
    PMU_ST_SLEEP = 3'd2,
    PMU_ST_DEEP  = 3'd3,
    PMU_ST_PD    = 3'd4,
    PMU_ST_PU    = 3'd5
  } pmu_status_state_e;

  localparam bit [31:0] PMU_ID_VALUE = 32'h504D_5501;
  localparam int        PMU_N_OPP    = 3;

  // ---------------------------------------------------------------------------
  class pmu_reg_id extends uvm_reg;
    `uvm_object_utils(pmu_reg_id)
    rand uvm_reg_field ID;
    function new(string name = "pmu_reg_id");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      ID = uvm_reg_field::type_id::create("ID");
      ID.configure(this, 32, 0, "RO", 0, PMU_ID_VALUE, 1, 0, 1);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_ctrl extends uvm_reg;
    `uvm_object_utils(pmu_reg_ctrl)
    rand uvm_reg_field PD_EN;
    rand uvm_reg_field RET_EN;

    covergroup cg_vals with function sample(bit pd_en, bit ret_en, bit is_read);
      option.per_instance = 1;
      cp_mode: coverpoint {pd_en, ret_en} iff (!is_read) {
        bins idle_only  = {2'b00};
        bins idle_ret   = {2'b01};   // RET_EN without PD_EN: still IDLE
        bins sleep      = {2'b10};
        bins deep_sleep = {2'b11};
      }
      cp_dir: coverpoint is_read;
    endgroup

    function new(string name = "pmu_reg_ctrl");
      super.new(name, 32, build_coverage(UVM_CVR_FIELD_VALS));
      if (has_coverage(UVM_CVR_FIELD_VALS)) cg_vals = new();
    endfunction
    virtual function void build();
      PD_EN  = uvm_reg_field::type_id::create("PD_EN");
      RET_EN = uvm_reg_field::type_id::create("RET_EN");
      PD_EN.configure (this, 1, 0, "RW", 0, 1'b0, 1, 1, 0);
      RET_EN.configure(this, 1, 1, "RW", 0, 1'b0, 1, 1, 0);
    endfunction
    virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en,
                                 bit is_read, uvm_reg_map map);
      if (get_coverage(UVM_CVR_FIELD_VALS)) cg_vals.sample(data[0], data[1], is_read);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_status extends uvm_reg;
    `uvm_object_utils(pmu_reg_status)
    uvm_reg_field STATE, CLK_EN, ISO_EN, RET_EN, PWR_EN, PWR_GOOD, CPU_RST_N, DVFS_CUR, DVFS_PEND;

    covergroup cg_vals with function sample(bit [2:0] st, bit [1:0] opp);
      option.per_instance = 1;
      cp_state: coverpoint st {
        bins run = {0}; bins idle = {1}; bins sleep = {2}; bins deep = {3};
        bins pd = {4}; bins pu = {5}; illegal_bins bad = {[6:7]};
      }
      cp_opp: coverpoint opp { bins opp[] = {[0:2]}; illegal_bins bad = {3}; }
    endgroup

    function new(string name = "pmu_reg_status");
      super.new(name, 32, build_coverage(UVM_CVR_FIELD_VALS));
      if (has_coverage(UVM_CVR_FIELD_VALS)) cg_vals = new();
    endfunction
    virtual function void build();
      STATE     = uvm_reg_field::type_id::create("STATE");
      CLK_EN    = uvm_reg_field::type_id::create("CLK_EN");
      ISO_EN    = uvm_reg_field::type_id::create("ISO_EN");
      RET_EN    = uvm_reg_field::type_id::create("RET_EN");
      PWR_EN    = uvm_reg_field::type_id::create("PWR_EN");
      PWR_GOOD  = uvm_reg_field::type_id::create("PWR_GOOD");
      CPU_RST_N = uvm_reg_field::type_id::create("CPU_RST_N");
      DVFS_CUR  = uvm_reg_field::type_id::create("DVFS_CUR");
      DVFS_PEND = uvm_reg_field::type_id::create("DVFS_PEND");
      //                        parent bits lsb  acc   vol reset has_rst rand indiv
      STATE.configure    (this, 3,   0,  "RO", 1,  3'd0, 0, 0, 0);
      CLK_EN.configure   (this, 1,   4,  "RO", 1,  1'b0, 0, 0, 0);
      ISO_EN.configure   (this, 1,   5,  "RO", 1,  1'b0, 0, 0, 0);
      RET_EN.configure   (this, 1,   6,  "RO", 1,  1'b0, 0, 0, 0);
      PWR_EN.configure   (this, 1,   7,  "RO", 1,  1'b0, 0, 0, 0);
      PWR_GOOD.configure (this, 1,   8,  "RO", 1,  1'b0, 0, 0, 0);
      CPU_RST_N.configure(this, 1,   9,  "RO", 1,  1'b0, 0, 0, 0);
      DVFS_CUR.configure (this, 2,  12,  "RO", 1,  2'd0, 0, 0, 0);
      DVFS_PEND.configure(this, 1,  16,  "RO", 1,  1'b0, 0, 0, 0);
    endfunction
    virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en,
                                 bit is_read, uvm_reg_map map);
      if (is_read && get_coverage(UVM_CVR_FIELD_VALS)) cg_vals.sample(data[2:0], data[13:12]);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_dvfs extends uvm_reg;
    `uvm_object_utils(pmu_reg_dvfs)
    rand uvm_reg_field OPP;
    constraint c_legal { OPP.value < PMU_N_OPP; }

    covergroup cg_vals with function sample(bit [1:0] opp, bit is_read);
      option.per_instance = 1;
      cp_opp_wr: coverpoint opp iff (!is_read) { bins opp[] = {[0:2]}; bins reserved = {3}; }
      cp_opp_rd: coverpoint opp iff (is_read)  { bins opp[] = {[0:2]}; illegal_bins reserved = {3}; }
    endgroup

    function new(string name = "pmu_reg_dvfs");
      super.new(name, 32, build_coverage(UVM_CVR_FIELD_VALS));
      if (has_coverage(UVM_CVR_FIELD_VALS)) cg_vals = new();
    endfunction
    virtual function void build();
      OPP = uvm_reg_field::type_id::create("OPP");
      OPP.configure(this, 2, 0, "RW", 0, 2'd0, 1, 1, 1);
    endfunction
    virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en,
                                 bit is_read, uvm_reg_map map);
      if (get_coverage(UVM_CVR_FIELD_VALS)) cg_vals.sample(data[1:0], is_read);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_wake_mask extends uvm_reg;
    `uvm_object_utils(pmu_reg_wake_mask)
    rand uvm_reg_field MASK;

    covergroup cg_vals with function sample(bit [7:0] m, bit is_read);
      option.per_instance = 1;
      cp_bits: coverpoint m iff (!is_read) {
        bins none   = {8'h00};
        bins all    = {8'hFF};
        bins single[] = {8'h01, 8'h02, 8'h04, 8'h08, 8'h10, 8'h20, 8'h40, 8'h80};
        bins multi  = default;
      }
    endgroup

    function new(string name = "pmu_reg_wake_mask");
      super.new(name, 32, build_coverage(UVM_CVR_FIELD_VALS));
      if (has_coverage(UVM_CVR_FIELD_VALS)) cg_vals = new();
    endfunction
    virtual function void build();
      MASK = uvm_reg_field::type_id::create("MASK");
      MASK.configure(this, 8, 0, "RW", 0, 8'hFF, 1, 1, 1);
    endfunction
    virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en,
                                 bit is_read, uvm_reg_map map);
      if (get_coverage(UVM_CVR_FIELD_VALS)) cg_vals.sample(data[7:0], is_read);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_wake_cause extends uvm_reg;
    `uvm_object_utils(pmu_reg_wake_cause)
    rand uvm_reg_field CAUSE;

    covergroup cg_vals with function sample(bit [7:0] c, bit is_read);
      option.per_instance = 1;
      cp_rd: coverpoint (c != 0) iff (is_read) { bins clear = {0}; bins set = {1}; }
      cp_w1c: coverpoint (c != 0) iff (!is_read) { bins w1c = {1}; bins noop = {0}; }
    endgroup

    function new(string name = "pmu_reg_wake_cause");
      super.new(name, 32, build_coverage(UVM_CVR_FIELD_VALS));
      if (has_coverage(UVM_CVR_FIELD_VALS)) cg_vals = new();
    endfunction
    virtual function void build();
      CAUSE = uvm_reg_field::type_id::create("CAUSE");
      CAUSE.configure(this, 8, 0, "W1C", 1, 8'h00, 1, 0, 1);
    endfunction
    virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en,
                                 bit is_read, uvm_reg_map map);
      if (get_coverage(UVM_CVR_FIELD_VALS)) cg_vals.sample(data[7:0], is_read);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_seq_delay extends uvm_reg;
    `uvm_object_utils(pmu_reg_seq_delay)
    rand uvm_reg_field DELAY;
    constraint c_sane { DELAY.value inside {[1:32]}; }

    covergroup cg_vals with function sample(bit [7:0] d, bit is_read);
      option.per_instance = 1;
      cp_delay: coverpoint d iff (!is_read) {
        bins zero = {0}; bins one = {1}; bins short_d = {[2:7]}; bins mid = {[8:31]}; bins long_d = {[32:255]};
      }
    endgroup

    function new(string name = "pmu_reg_seq_delay");
      super.new(name, 32, build_coverage(UVM_CVR_FIELD_VALS));
      if (has_coverage(UVM_CVR_FIELD_VALS)) cg_vals = new();
    endfunction
    virtual function void build();
      DELAY = uvm_reg_field::type_id::create("DELAY");
      DELAY.configure(this, 8, 0, "RW", 0, 8'd4, 1, 1, 1);
    endfunction
    virtual function void sample(uvm_reg_data_t data, uvm_reg_data_t byte_en,
                                 bit is_read, uvm_reg_map map);
      if (get_coverage(UVM_CVR_FIELD_VALS)) cg_vals.sample(data[7:0], is_read);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_pd_count extends uvm_reg;
    `uvm_object_utils(pmu_reg_pd_count)
    uvm_reg_field COUNT;
    function new(string name = "pmu_reg_pd_count");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      COUNT = uvm_reg_field::type_id::create("COUNT");
      COUNT.configure(this, 16, 0, "RO", 1, 16'd0, 1, 0, 1);
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  // Registers physically inside PD_CPU (power-gated, not retained)
  class pmu_reg_scratch extends uvm_reg;
    `uvm_object_utils(pmu_reg_scratch)
    rand uvm_reg_field DATA;
    function new(string name = "pmu_reg_scratch");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      DATA = uvm_reg_field::type_id::create("DATA");
      DATA.configure(this, 32, 0, "RW", 0, 32'h0, 1, 1, 1);
    endfunction
  endclass

  class pmu_cpu_win_block extends uvm_reg_block;
    `uvm_object_utils(pmu_cpu_win_block)
    rand pmu_reg_scratch SCRATCH[4];
    function new(string name = "pmu_cpu_win_block");
      super.new(name, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      default_map = create_map("map", 'h0, 4, UVM_LITTLE_ENDIAN, 1);
      foreach (SCRATCH[i]) begin
        SCRATCH[i] = pmu_reg_scratch::type_id::create($sformatf("SCRATCH%0d", i));
        SCRATCH[i].configure(this);
        SCRATCH[i].build();
        default_map.add_reg(SCRATCH[i], 4 * i, "RW");
      end
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_reg_block extends uvm_reg_block;
    `uvm_object_utils(pmu_reg_block)

    rand pmu_reg_id         ID;
    rand pmu_reg_ctrl       CTRL;
    rand pmu_reg_status     STATUS;
    rand pmu_reg_dvfs       DVFS;
    rand pmu_reg_wake_mask  WAKE_MASK;
    rand pmu_reg_wake_cause WAKE_CAUSE;
    rand pmu_reg_seq_delay  SEQ_DELAY;
    rand pmu_reg_pd_count   PD_COUNT;
    rand pmu_cpu_win_block  CPU_WIN;

    function new(string name = "pmu_reg_block");
      super.new(name, build_coverage(UVM_CVR_FIELD_VALS));
    endfunction

    // base_addr: where the PMU sits on the AXI4-Lite bus
    virtual function void build(uvm_reg_addr_t base_addr = 'h0);
      default_map = create_map("default_map", base_addr, 4, UVM_LITTLE_ENDIAN, 1);

      ID         = pmu_reg_id::type_id::create("ID");
      CTRL       = pmu_reg_ctrl::type_id::create("CTRL");
      STATUS     = pmu_reg_status::type_id::create("STATUS");
      DVFS       = pmu_reg_dvfs::type_id::create("DVFS");
      WAKE_MASK  = pmu_reg_wake_mask::type_id::create("WAKE_MASK");
      WAKE_CAUSE = pmu_reg_wake_cause::type_id::create("WAKE_CAUSE");
      SEQ_DELAY  = pmu_reg_seq_delay::type_id::create("SEQ_DELAY");
      PD_COUNT   = pmu_reg_pd_count::type_id::create("PD_COUNT");

      ID.configure(this);         ID.build();
      CTRL.configure(this);       CTRL.build();
      STATUS.configure(this);     STATUS.build();
      DVFS.configure(this);       DVFS.build();
      WAKE_MASK.configure(this);  WAKE_MASK.build();
      WAKE_CAUSE.configure(this); WAKE_CAUSE.build();
      SEQ_DELAY.configure(this);  SEQ_DELAY.build();
      PD_COUNT.configure(this);   PD_COUNT.build();

      default_map.add_reg(ID,         'h000, "RO");
      default_map.add_reg(CTRL,       'h004, "RW");
      default_map.add_reg(STATUS,     'h008, "RO");
      default_map.add_reg(DVFS,       'h00C, "RW");
      default_map.add_reg(WAKE_MASK,  'h010, "RW");
      default_map.add_reg(WAKE_CAUSE, 'h014, "RW");
      default_map.add_reg(SEQ_DELAY,  'h018, "RW");
      default_map.add_reg(PD_COUNT,   'h01C, "RO");

      CPU_WIN = pmu_cpu_win_block::type_id::create("CPU_WIN");
      CPU_WIN.configure(this);
      CPU_WIN.build();
      default_map.add_submap(CPU_WIN.default_map, 'h100);

      // Built-in test exclusions:
      //  * DVFS: writing the reserved OPP value returns SLVERR by design, so
      //    a walking-ones bit bash cannot pass; it is covered by pmu_err_test.
      uvm_resource_db#(bit)::set({"REG::", DVFS.get_full_name()}, "NO_REG_BIT_BASH_TEST", 1, this);
      //  * CPU_WIN: accessible only while PD_CPU runs; the test sequence keeps
      //    the CPU running, so these are included in the built-in tests.

      lock_model();
    endfunction

    // True if `rg` lives in the switchable power domain
    function bit in_pd_cpu(uvm_reg rg);
      return (rg != null) && (rg.get_parent() == CPU_WIN);
    endfunction

  endclass

endpackage
// ---- end ral/pmu_ral_pkg.sv ----

// ---- begin env/pmu_env_pkg.sv ----
// -----------------------------------------------------------------------------
// pmu_env_pkg.sv - PMU subsystem verification environment
//
// Combines the AXI4-Lite agent, the power agent and the PMU register model
// with a reference model / scoreboard, functional coverage and a virtual
// sequence library for every power-state transition and DVFS change.
// -----------------------------------------------------------------------------
package pmu_env_pkg;

  import uvm_pkg::*;
  `include "uvm_macros.svh"
  import axi_lite_pkg::*;
  import pwr_pkg::*;
  import pmu_ral_pkg::*;


// ---- begin env/pmu_env_types.svh ----
// pmu_env_types.svh - types shared by the PMU environment

// Reference-model view of PD_CPU. RUN/IDLE/SLEEP/DEEP are the stable CPU
// power states from SPEC.md; PD/PU are the sequencing phases between them.
typedef enum {
  PMU_RESET,   // PD_AON reset asserted
  PMU_RUN,
  PMU_IDLE,
  PMU_PD,      // power-down sequence in progress
  PMU_SLEEP,
  PMU_DEEP,    // DEEP_SLEEP
  PMU_PU       // power-up sequence in progress (wake or cold boot)
} pmu_state_e;

// Why a bus access is expected to fail
typedef enum {
  PMU_ERR_NONE,
  PMU_ERR_UNMAPPED,     // no register at that address           -> DECERR
  PMU_ERR_RESERVED,     // reserved field value                  -> SLVERR
  PMU_ERR_DOMAIN_OFF    // register in a domain that is not up   -> SLVERR
} pmu_err_reason_e;

// Individual control-pin events seen on the power interface
typedef enum {
  EV_CLK_ON, EV_CLK_OFF,
  EV_ISO_ON, EV_ISO_OFF,
  EV_RST_ASSERT, EV_RST_RELEASE,
  EV_RET_ON, EV_RET_OFF,
  EV_PWR_ON, EV_PWR_OFF
} pmu_pin_ev_e;

function automatic bit pmu_is_stable(pmu_state_e s);
  return s inside {PMU_RUN, PMU_IDLE, PMU_SLEEP, PMU_DEEP};
endfunction

// Completed transition between stable states (or a DVFS change in IDLE),
// published by the scoreboard for coverage.
class pmu_trans_item extends uvm_sequence_item;
  pmu_state_e  from_st, to_st;
  bit          is_dvfs;        // DVFS mux change (from_st == to_st == IDLE)
  bit [1:0]    opp_from, opp_to;
  int unsigned dwell_cycles;   // cycles spent in from_st
  bit          wake_during_pd; // wake request already pending when OFF was reached
  realtime     t;
  `uvm_object_utils(pmu_trans_item)
  function new(string name = "pmu_trans_item"); super.new(name); endfunction
  function string convert2string();
    if (is_dvfs) return $sformatf("DVFS OPP%0d -> OPP%0d @%0t", opp_from, opp_to, t);
    return $sformatf("%s -> %s (dwell %0d) @%0t", from_st.name(), to_st.name(), dwell_cycles, t);
  endfunction
endclass

// Bus access classified by the scoreboard, published for coverage.
class pmu_bus_item extends uvm_sequence_item;
  axi_lite_item     tr;
  int               reg_idx;     // index into pmu_env_cfg::reg_names, -1 = unmapped
  bit               in_pd_cpu;
  pmu_state_e       st;          // model state when the request was accepted
  pmu_err_reason_e  reason;
  axi_lite_resp_e   exp_resp;
  bit               boundary;    // domain changed state during the access
  `uvm_object_utils(pmu_bus_item)
  function new(string name = "pmu_bus_item"); super.new(name); endfunction
endclass
// ---- end env/pmu_env_types.svh ----

// ---- begin env/pmu_env_cfg.svh ----
// pmu_env_cfg.svh - PMU environment configuration
class pmu_env_cfg extends uvm_object;

  axi_lite_cfg  axi_cfg;
  pwr_cfg       pwr_cfg_h;

  // Register model (created by the env if left null)
  pmu_reg_block ral;

  // Address of the PMU register block on the AXI4-Lite bus
  bit [31:0]    base_addr = 32'h0;

  // DUT properties needed by the reference model
  bit [`PWR_ISO_W-1:0] iso_clamp = 16'h00F0;  // value of every isolated output when clamped
  int unsigned  n_opp           = PMU_N_OPP;  // legal DVFS operating points
  axi_lite_resp_e unmapped_resp = AXI_DECERR;
  axi_lite_resp_e off_domain_resp = AXI_SLVERR;
  axi_lite_resp_e reserved_resp = AXI_SLVERR;

  bit has_scoreboard = 1;
  bit has_coverage   = 1;

  // Checks that can be relaxed for a DUT that intentionally differs
  bit check_invariants  = 1;  // static relations between gate/iso/reset/switch
  bit check_dvfs_done   = 1;  // a DVFS change pending at IDLE entry completes in IDLE
  bit check_status_reg  = 1;  // STATUS read value vs. observed pins/model

  // Timeouts used by virtual sequences (clk_aon cycles)
  int unsigned state_timeout = 20000;

  `uvm_object_utils_begin(pmu_env_cfg)
    `uvm_field_int(base_addr, UVM_DEFAULT)
    `uvm_field_int(iso_clamp, UVM_DEFAULT)
    `uvm_field_int(n_opp, UVM_DEFAULT | UVM_DEC)
    `uvm_field_int(has_scoreboard, UVM_DEFAULT)
    `uvm_field_int(has_coverage, UVM_DEFAULT)
    `uvm_field_int(check_invariants, UVM_DEFAULT)
    `uvm_field_int(check_dvfs_done, UVM_DEFAULT)
    `uvm_field_int(check_status_reg, UVM_DEFAULT)
    `uvm_field_int(state_timeout, UVM_DEFAULT | UVM_DEC)
  `uvm_object_utils_end

  function new(string name = "pmu_env_cfg");
    super.new(name);
    axi_cfg   = axi_lite_cfg::type_id::create("axi_cfg");
    pwr_cfg_h = pwr_cfg::type_id::create("pwr_cfg");
  endfunction

endclass
// ---- end env/pmu_env_cfg.svh ----

// ---- begin env/pmu_state_tracker.svh ----
// pmu_state_tracker.svh - current reference-model state, shared with sequences
//
// Updated only by the scoreboard (from observed pins). Virtual sequences use
// it to wait for power states without peeking at DUT internals.
class pmu_state_tracker extends uvm_object;
  `uvm_object_utils(pmu_state_tracker)

  pmu_state_e    cur = PMU_RESET;
  pmu_state_e    last_stable = PMU_RESET;
  bit [1:0]      opp;
  event          changed;
  virtual pwr_if vif;   // for cycle-based timeouts

  function new(string name = "pmu_state_tracker");
    super.new(name);
  endfunction

  function void set(pmu_state_e s);
    if (s != cur) begin
      cur = s;
      if (pmu_is_stable(s)) last_stable = s;
      -> changed;
    end
  endfunction

  // Wait until the model is in state s; returns 0 on timeout.
  task wait_for(pmu_state_e s, int unsigned max_cycles, output bit ok);
    bit got = 0;
    fork begin               // isolate: disable fork only kills our children
      fork
        begin
          while (cur != s) @(changed);
          got = 1;
        end
        repeat (max_cycles) @(posedge vif.clk);
      join_any
      disable fork;
    end join
    ok = got;
  endtask

  // Wait until the model leaves state s; returns 0 on timeout.
  task wait_leave(pmu_state_e s, int unsigned max_cycles, output bit ok);
    bit got = 0;
    fork begin
      fork
        begin
          while (cur == s) @(changed);
          got = 1;
        end
        repeat (max_cycles) @(posedge vif.clk);
      join_any
      disable fork;
    end join
    ok = got;
  endtask

endclass
// ---- end env/pmu_state_tracker.svh ----

// ---- begin env/pmu_scoreboard.svh ----
// pmu_scoreboard.svh - reference model of PMU power sequencing + bus checker
//
// Inputs
//   axi_imp : completed AXI4-Lite transactions (with handshake timestamps)
//   pwr_imp : power-interface snapshots (published on every change)
//
// Power checks (from pins only, so any PMU implementation can be checked)
//   * power-down order : clock gate -> isolation on -> reset assert
//                        -> [retention on, DEEP_SLEEP] -> switch off
//   * wake-up order    : switch on -> power_good -> [retention off]
//                        -> reset release -> isolation off -> clock on
//   * one control pin per clock edge during sequencing (strict order)
//   * IDLE entered only on WFI, left only on an enabled wake source
//   * DVFS mux changes only in IDLE, only to the programmed legal OPP, never
//     together with the clock enable, and a pending change completes in IDLE
//   * isolation clamps: isolated outputs == clamp value while isolation is on,
//     == raw domain outputs otherwise
//   * static invariants between gate / isolation / reset / switch / power_good
//
// Bus checks
//   * response code: DECERR for unmapped, SLVERR for reserved values and for
//     PD_CPU registers while PD_CPU is not RUNning, OKAY otherwise. An access
//     that overlaps a domain state change may legally get either response.
//   * read data of non-volatile PD_AON registers: by the RAL predictor
//     (check_on_read on the PMU map).
//   * read data of PD_CPU registers: by this scoreboard, which models their
//     loss on domain reset (not retained) and orders each access against the
//     reset using the bus timestamps.
//   * volatile registers (STATUS, WAKE_CAUSE, PD_COUNT): against the model.
//
// The register-specific parts are virtual functions so a derived scoreboard
// can adapt them to a different PMU register map via a factory override.

`uvm_analysis_imp_decl(_axi)
`uvm_analysis_imp_decl(_pwr)

class pmu_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(pmu_scoreboard)

  uvm_analysis_imp_axi #(axi_lite_item, pmu_scoreboard) axi_imp;
  uvm_analysis_imp_pwr #(pwr_obs, pmu_scoreboard)       pwr_imp;
  uvm_analysis_port #(pmu_trans_item)                   trans_ap;
  uvm_analysis_port #(pmu_bus_item)                     bus_ap;

  pmu_env_cfg       cfg;
  pmu_reg_block     ral;
  pmu_state_tracker tracker;

  // ---------------- reference model state ----------------
  protected pmu_state_e  st = PMU_RESET;
  protected pmu_state_e  last_stable = PMU_RESET;
  protected longint unsigned stable_since_cyc;
  protected longint unsigned left_stable_cyc;   // when the last stable state was left
  protected pmu_pin_ev_e exp_q[$];
  protected bit          mode_deep;
  protected bit          wake_seen;         // enabled wake source seen since entering low power
  protected bit          wake_seen_at_off;  // ... already when OFF was reached
  protected bit [7:0]    wake_bits_seen;
  protected bit          dvfs_pend_at_idle;
  protected pwr_obs      last;

  // register shadow (updated by OKAY writes)
  protected bit          sh_pd_en, sh_ret_en;
  protected bit [1:0]    sh_opp;
  protected bit [7:0]    sh_mask = 8'hFF;

  // volatile-register expectations
  protected bit [7:0]    cause_possible;   // bits that may be set in WAKE_CAUSE
  protected realtime     last_wake_t = -1;
  protected realtime     pd_done_t[$];     // times power-down completed

  // PD_CPU register contents (not retained across power-off)
  protected bit [31:0]   win_val[uvm_reg];
  protected bit [31:0]   win_before_reset[uvm_reg];
  protected realtime     last_dom_reset_t = -1;

  // history for correlating bus accesses with the domain state
  typedef struct {
    realtime    t;
    pmu_state_e st;
    pwr_obs     o;
  } hist_t;
  protected hist_t hist[$];

  protected uvm_reg all_regs[$];

  // ---------------- statistics ----------------
  int unsigned n_snapshots, n_clamp_checks, n_seq_steps, n_transitions, n_dvfs;
  int unsigned n_bus, n_bus_err_resp, n_boundary, n_status_checks;
  int unsigned n_fail;

  function new(string name, uvm_component parent);
    super.new(name, parent);
    axi_imp  = new("axi_imp", this);
    pwr_imp  = new("pwr_imp", this);
    trans_ap = new("trans_ap", this);
    bus_ap   = new("bus_ap", this);
  endfunction

  function void end_of_elaboration_phase(uvm_phase phase);
    if (ral == null) `uvm_fatal("SB", "register model not set")
    ral.get_registers(all_regs);
    sh_mask = ral.WAKE_MASK.MASK.get_reset();
    sh_opp  = ral.DVFS.OPP.get_reset();
  endfunction

  // Error reporting that also counts (used for the self-check summary)
  protected function void fail(string id, string msg);
    n_fail++;
    `uvm_error(id, msg)
  endfunction

  // =========================================================================
  // Sequencing rules (override for a PMU with a different documented order)
  // =========================================================================
  virtual function void pd_sequence(bit deep, ref pmu_pin_ev_e q[$]);
    q.delete();
    q.push_back(EV_ISO_ON);
    q.push_back(EV_RST_ASSERT);
    if (deep) q.push_back(EV_RET_ON);
    q.push_back(EV_PWR_OFF);
  endfunction

  // Remaining power-up steps given the pins at the start of power-up
  virtual function void pu_sequence(pwr_obs o, ref pmu_pin_ev_e q[$]);
    q.delete();
    if (!o.pwr_en)   q.push_back(EV_PWR_ON);
    if (o.ret_en)    q.push_back(EV_RET_OFF);
    if (!o.dom_rst_n) q.push_back(EV_RST_RELEASE);
    if (o.iso_en)    q.push_back(EV_ISO_OFF);
    if (!o.clk_en)   q.push_back(EV_CLK_ON);
  endfunction

  // =========================================================================
  // Power interface
  // =========================================================================
  function void write_pwr(pwr_obs o);
    pwr_obs p = last;
    pmu_pin_ev_e evs[$];
    bit dvfs_chg;

    n_snapshots++;
    last = o;

    if (!o.rst_n) begin
      if (st != PMU_RESET) begin
        set_state(PMU_RESET, o);
        exp_q.delete();
        ral.reset();
        sh_pd_en = 0; sh_ret_en = 0;
        sh_opp  = ral.DVFS.OPP.get_reset();
        sh_mask = ral.WAKE_MASK.MASK.get_reset();
        cause_possible = 0;
        pd_done_t.delete();
        win_val.delete();
        win_before_reset.delete();
      end
      // Outputs are only defined once the reset has been applied; they are
      // checked from the first snapshot after reset release.
      record(o);
      return;
    end

    // Reset release: cold boot brings PD_CPU up without a wake source
    if (p == null || !p.rst_n) begin
      if (o.has_x) fail("SB_X", {"X/Z on a PMU power output after reset: ", o.convert2string()});
      check_clamp(o);
      if (cfg.check_invariants) check_invariants(o);
      set_state(PMU_PU, o);
      pu_sequence(o, exp_q);
      if (exp_q.size() == 0) set_state(PMU_RUN, o);
      record(o);
      return;
    end

    if (o.has_x) fail("SB_X", {"X/Z on a PMU power output: ", o.convert2string()});

    check_clamp(o);
    if (cfg.check_invariants) check_invariants(o);

    // Wake sources seen while in (or entering) a low-power state
    if (st inside {PMU_IDLE, PMU_PD, PMU_SLEEP, PMU_DEEP}) begin
      bit [7:0] hit = o.wake_irq & sh_mask;
      if (hit != 0) begin
        wake_seen = 1;
        wake_bits_seen |= hit;
      end
    end

    // Decode control-pin edges
    if (p.clk_en    != o.clk_en)    evs.push_back(o.clk_en    ? EV_CLK_ON      : EV_CLK_OFF);
    if (p.iso_en    != o.iso_en)    evs.push_back(o.iso_en    ? EV_ISO_ON      : EV_ISO_OFF);
    if (p.dom_rst_n != o.dom_rst_n) evs.push_back(o.dom_rst_n ? EV_RST_RELEASE : EV_RST_ASSERT);
    if (p.ret_en    != o.ret_en)    evs.push_back(o.ret_en    ? EV_RET_ON      : EV_RET_OFF);
    if (p.pwr_en    != o.pwr_en)    evs.push_back(o.pwr_en    ? EV_PWR_ON      : EV_PWR_OFF);
    dvfs_chg = (p.dvfs_sel != o.dvfs_sel);

    if (evs.size() > 1) begin
      string s = "";
      foreach (evs[i]) s = {s, " ", evs[i].name()};
      fail("SB_ORDER", $sformatf("%0d power controls changed on the same clock edge (%s) in %s: steps must be strictly ordered",
                                 evs.size(), s, st.name()));
    end

    if (dvfs_chg) check_dvfs(p, o, evs);

    foreach (evs[i]) process_event(evs[i], p, o);

    record(o);
  endfunction

  protected function void process_event(pmu_pin_ev_e ev, pwr_obs p, pwr_obs o);
    n_seq_steps++;
    if (ev == EV_RST_ASSERT) domain_reset(o);
    case (st)
      PMU_RUN: begin
        if (ev == EV_CLK_OFF) begin
          if (!(p.wfi || o.wfi))
            fail("SB_WFI", $sformatf("clock gated in RUN without WFI @%0t", o.t));
          wake_seen = 0;
          wake_bits_seen = 0;
          if (sh_pd_en) begin
            mode_deep = sh_ret_en;
            pd_sequence(mode_deep, exp_q);
            set_state(PMU_PD, o);
          end else begin
            dvfs_pend_at_idle = (sh_opp != o.dvfs_sel);
            set_state(PMU_IDLE, o);
          end
        end else begin
          fail("SB_ORDER", $sformatf("unexpected %s in RUN (power-down must start with the clock gate) @%0t",
                                     ev.name(), o.t));
        end
      end

      PMU_IDLE: begin
        if (ev == EV_CLK_ON) begin
          if (!wake_seen)
            fail("SB_WAKE", $sformatf("left IDLE without an enabled wake source (mask=0x%02h irq=0x%02h) @%0t",
                                      sh_mask, o.wake_irq, o.t));
          if (cfg.check_dvfs_done && dvfs_pend_at_idle && o.dvfs_sel != sh_opp)
            fail("SB_DVFS", $sformatf("DVFS change to OPP%0d pending at IDLE entry was not applied before wake (still OPP%0d)",
                                      sh_opp, o.dvfs_sel));
          note_wake(p, o);
          set_state(PMU_RUN, o);
        end else begin
          fail("SB_ORDER", $sformatf("unexpected %s in IDLE (only clock-on may follow) @%0t", ev.name(), o.t));
        end
      end

      PMU_PD, PMU_PU: begin
        expect_step(ev, o);
        if (exp_q.size() == 0) begin
          if (st == PMU_PD) begin
            wake_seen_at_off = wake_seen;
            pd_done_t.push_back(o.t);
            set_state(mode_deep ? PMU_DEEP : PMU_SLEEP, o);
          end else begin
            set_state(PMU_RUN, o);
          end
        end
      end

      PMU_SLEEP, PMU_DEEP: begin
        if (ev == EV_PWR_ON) begin
          if (!wake_seen)
            fail("SB_WAKE", $sformatf("power switched on in %s without an enabled wake source (mask=0x%02h irq=0x%02h) @%0t",
                                      st.name(), sh_mask, o.wake_irq, o.t));
          if ((st == PMU_DEEP) != o.ret_en)
            fail("SB_RET", $sformatf("retention is %0b while in %s", o.ret_en, st.name()));
          note_wake(p, o);
          pu_sequence(o, exp_q);
          set_state(PMU_PU, o);
        end else begin
          fail("SB_ORDER", $sformatf("unexpected %s in %s (only switch-on may follow) @%0t", ev.name(), st.name(), o.t));
        end
      end

      default: fail("SB_ORDER", $sformatf("unexpected %s in %s @%0t", ev.name(), st.name(), o.t));
    endcase
  endfunction

  // Compare one sequencing step with the head of the expected queue
  protected function void expect_step(pmu_pin_ev_e ev, pwr_obs o);
    int idx = -1;
    foreach (exp_q[i]) if (exp_q[i] == ev) begin idx = i; break; end
    if (idx == 0) begin
      exp_q.pop_front();
    end else begin
      string s = "";
      foreach (exp_q[i]) s = {s, " ", exp_q[i].name()};
      fail("SB_ORDER", $sformatf("%s: got %s, expected next %s (remaining:%s) @%0t",
                                 st.name(), ev.name(), exp_q.size() ? exp_q[0].name() : "<none>", s, o.t));
      // resynchronise: drop everything up to and including the event
      if (idx > 0) repeat (idx + 1) void'(exp_q.pop_front());
    end
    // Steps that need the supply to be good
    if (ev inside {EV_RET_OFF, EV_RST_RELEASE, EV_ISO_OFF, EV_CLK_ON} && !o.pwr_good)
      fail("SB_PGOOD", $sformatf("%s before power_good @%0t", ev.name(), o.t));
  endfunction

  protected function void check_dvfs(pwr_obs p, pwr_obs o, pmu_pin_ev_e evs[$]);
    pmu_trans_item tr;
    n_dvfs++;
    if (st != PMU_IDLE)
      fail("SB_DVFS", $sformatf("DVFS mux changed OPP%0d->OPP%0d in %s (allowed only in IDLE) @%0t",
                                p.dvfs_sel, o.dvfs_sel, st.name(), o.t));
    if (o.clk_en || (EV_CLK_ON inside {evs}))
      fail("SB_DVFS", $sformatf("DVFS mux changed while the clock is enabled @%0t", o.t));
    if (o.dvfs_sel >= cfg.n_opp)
      fail("SB_DVFS", $sformatf("DVFS mux set to reserved OPP%0d", o.dvfs_sel));
    else if (o.dvfs_sel != sh_opp)
      fail("SB_DVFS", $sformatf("DVFS mux set to OPP%0d, programmed OPP%0d", o.dvfs_sel, sh_opp));
    tr = pmu_trans_item::type_id::create("dvfs");
    tr.is_dvfs  = 1;
    tr.from_st  = st;
    tr.to_st    = st;
    tr.opp_from = p.dvfs_sel;
    tr.opp_to   = o.dvfs_sel;
    tr.t        = o.t;
    tracker.opp = o.dvfs_sel;
    `uvm_info("SB", tr.convert2string(), UVM_MEDIUM)
    trans_ap.write(tr);
  endfunction

  protected function void check_clamp(pwr_obs o);
    bit [`PWR_ISO_W-1:0] exp = o.iso_en ? cfg.iso_clamp : o.dom_out;
    n_clamp_checks++;
    if (o.dom_out_iso != exp)
      fail("SB_ISO", $sformatf("isolated outputs 0x%0h, expected 0x%0h (iso_en=%0b raw=0x%0h) @%0t",
                               o.dom_out_iso, exp, o.iso_en, o.dom_out, o.t));
  endfunction

  protected function void check_invariants(pwr_obs o);
    if (o.clk_en && (o.iso_en || !o.dom_rst_n || !o.pwr_en || !o.pwr_good))
      fail("SB_INV", {"domain clock enabled while isolated/in reset/unpowered: ", o.convert2string()});
    if (!o.iso_en && (!o.dom_rst_n || !o.pwr_en || !o.pwr_good))
      fail("SB_INV", {"isolation off while domain in reset/unpowered: ", o.convert2string()});
    if (o.ret_en && o.dom_rst_n)
      fail("SB_INV", {"retention enabled while domain out of reset: ", o.convert2string()});
    if (!o.pwr_en && o.dom_rst_n)
      fail("SB_INV", {"power switch off while domain reset released: ", o.convert2string()});
  endfunction

  protected function void note_wake(pwr_obs p, pwr_obs o);
    cause_possible |= wake_bits_seen | (o.wake_irq & sh_mask);
    last_wake_t = o.t;
  endfunction

  // PD_CPU reset: its registers return to their reset values
  protected function void domain_reset(pwr_obs o);
    win_before_reset = win_val;
    win_val.delete();
    last_dom_reset_t = o.t;
    ral.CPU_WIN.reset();
  endfunction

  protected function void set_state(pmu_state_e s, pwr_obs o);
    if (s == st) return;
    `uvm_info("SB", $sformatf("state %s -> %s @%0t", st.name(), s.name(), o.t), UVM_HIGH)
    if (pmu_is_stable(st) || st == PMU_RESET) left_stable_cyc = o.cycle;
    if (pmu_is_stable(s) || (s == PMU_RESET)) begin
      if (pmu_is_stable(s)) begin
        pmu_trans_item tr = pmu_trans_item::type_id::create("tr");
        tr.from_st        = last_stable;
        tr.to_st          = s;
        tr.dwell_cycles   = int'(left_stable_cyc - stable_since_cyc);   // time in from_st only
        tr.wake_during_pd = (s inside {PMU_SLEEP, PMU_DEEP}) && wake_seen_at_off;
        tr.opp_from       = o.dvfs_sel;
        tr.opp_to         = o.dvfs_sel;
        tr.t              = o.t;
        n_transitions++;
        `uvm_info("SB", tr.convert2string(), UVM_MEDIUM)
        trans_ap.write(tr);
      end
      last_stable      = s;
      stable_since_cyc = o.cycle;
    end
    st = s;
    if (tracker != null) tracker.set(s);
  endfunction

  protected function void record(pwr_obs o);
    hist_t h;
    h.t  = o.t;
    h.st = st;
    h.o  = o;
    hist.push_back(h);
    if (hist.size() > 512) void'(hist.pop_front());
  endfunction

  // Model history entries covering [t0, t1): the entry in force at t0 plus
  // every later entry before t1.
  protected function void window(realtime t0, realtime t1, ref hist_t w[$]);
    int first = -1;
    w.delete();
    for (int i = hist.size() - 1; i >= 0; i--)
      if (hist[i].t <= t0) begin first = i; break; end
    if (first < 0) first = 0;
    for (int i = first; i < hist.size(); i++)
      if (i == first || hist[i].t < t1) w.push_back(hist[i]);
  endfunction

  // =========================================================================
  // Bus
  // =========================================================================

  // Expected response for a register that exists and is reachable.
  virtual function axi_lite_resp_e reg_resp(uvm_reg rg, axi_lite_item t, ref pmu_err_reason_e why);
    why = PMU_ERR_NONE;
    if (rg == ral.DVFS && t.kind == AXI_WRITE && t.strb[0] && t.data[1:0] >= cfg.n_opp) begin
      why = PMU_ERR_RESERVED;
      return cfg.reserved_resp;
    end
    return AXI_OKAY;
  endfunction

  // Track writes that change sequencing behaviour.
  virtual function void update_shadow(uvm_reg rg, axi_lite_item t);
    if (!t.strb[0]) return;
    if (rg == ral.CTRL) begin
      sh_pd_en  = t.data[ral.CTRL.PD_EN.get_lsb_pos()];
      sh_ret_en = t.data[ral.CTRL.RET_EN.get_lsb_pos()];
    end else if (rg == ral.DVFS) begin
      sh_opp = t.data[1:0];
    end else if (rg == ral.WAKE_MASK) begin
      sh_mask = t.data[7:0];
    end else if (rg == ral.WAKE_CAUSE) begin
      // A clear that overlapped a wake-up may have executed before the wake
      // set its bits; keep them possible in that case.
      if (last_wake_t < t.t_req) cause_possible &= ~t.data[7:0];
    end
  endfunction

  function void write_axi(axi_lite_item t);
    pmu_bus_item     b = pmu_bus_item::type_id::create("bus");
    uvm_reg          rg;
    hist_t           w[$];
    bit              any_run, any_off;
    axi_lite_resp_e  exp;
    pmu_err_reason_e why = PMU_ERR_NONE;

    n_bus++;
    if (t.resp != AXI_OKAY) n_bus_err_resp++;
    rg = ral.default_map.get_reg_by_offset(t.addr, t.kind == AXI_READ);
    window(t.t_req, t.t_resp, w);
    foreach (w[i]) begin
      if (w[i].st == PMU_RUN) any_run = 1;
      else                    any_off = 1;
    end

    b.tr        = t;
    b.st        = w.size() ? w[0].st : st;
    b.reg_idx   = -1;
    b.in_pd_cpu = 0;
    foreach (all_regs[i]) if (all_regs[i] == rg) b.reg_idx = i;

    if (rg == null) begin
      why = PMU_ERR_UNMAPPED;
      exp = cfg.unmapped_resp;
    end else if (ral.in_pd_cpu(rg)) begin
      b.in_pd_cpu = 1;
      if (any_run && any_off) begin
        b.boundary = 1;
        n_boundary++;
        exp = t.resp;   // either answer is legal; checked below
        if (t.resp != AXI_OKAY && t.resp != cfg.off_domain_resp)
          fail("SB_RESP", $sformatf("PD_CPU access at a power-state boundary got %s: %s",
                                    t.resp.name(), t.convert2string()));
        if (t.resp != AXI_OKAY) why = PMU_ERR_DOMAIN_OFF;
      end else if (any_off) begin
        why = PMU_ERR_DOMAIN_OFF;
        exp = cfg.off_domain_resp;
      end else begin
        exp = reg_resp(rg, t, why);
      end
    end else begin
      exp = reg_resp(rg, t, why);
    end

    b.reason   = why;
    b.exp_resp = exp;
    if (t.resp != exp)
      fail("SB_RESP", $sformatf("expected %s (%s, PD_CPU %s), got %s: %s",
                                exp.name(), why.name(), b.st.name(), t.resp.name(), t.convert2string()));

    if (rg != null && t.resp == AXI_OKAY) begin
      if (b.in_pd_cpu)              check_pd_cpu_data(rg, t);
      else if (t.kind == AXI_WRITE) update_shadow(rg, t);
      else                          check_volatile(rg, t, w);
    end
    `uvm_info("SB", $sformatf("%s -> %s [%s]", t.convert2string(), rg == null ? "<unmapped>" : rg.get_name(),
                              why.name()), UVM_HIGH)
    bus_ap.write(b);
  endfunction

  // PD_CPU register data. An OKAY access was executed while PD_CPU was
  // running, i.e. before any domain reset that happened after its request.
  protected function void check_pd_cpu_data(uvm_reg rg, axi_lite_item t);
    bit before_reset = (last_dom_reset_t >= t.t_req);
    if (t.kind == AXI_WRITE) begin
      bit [31:0] v = win_val.exists(rg) ? win_val[rg] : 32'(rg.get_reset());
      if (before_reset) return;   // overwritten by the domain reset since
      for (int i = 0; i < 4; i++) if (t.strb[i]) v[8*i +: 8] = t.data[8*i +: 8];
      win_val[rg] = v;
    end else begin
      bit [31:0] e;
      if (before_reset) e = win_before_reset.exists(rg) ? win_before_reset[rg] : 32'(rg.get_reset());
      else              e = win_val.exists(rg)          ? win_val[rg]          : 32'(rg.get_reset());
      if (t.data != e)
        fail("SB_DATA", $sformatf("%s read 0x%08h, expected 0x%08h%s", rg.get_name(), t.data, e,
                                  before_reset ? " (value before PD_CPU reset)" : ""));
    end
  endfunction

  // Read-data checks for registers the RAL treats as volatile
  virtual function void check_volatile(uvm_reg rg, axi_lite_item t, hist_t w[$]);
    if (rg == ral.STATUS && cfg.check_status_reg) begin
      bit match = 0;
      n_status_checks++;
      foreach (w[i]) if (status_matches(t.data, w[i])) match = 1;
      if (!match)
        fail("SB_STATUS", $sformatf("STATUS=0x%08h does not match any model state/pins during the read (state %s, pins %s)",
                                    t.data, w[0].st.name(), w[0].o.convert2string()));
    end else if (rg == ral.WAKE_CAUSE) begin
      bit [7:0] v = t.data[7:0];
      bit recent = (last_wake_t >= t.t_req);   // wake raced with the read
      if (!recent && (v & ~cause_possible) != 0)
        fail("SB_WAKE_CAUSE", $sformatf("WAKE_CAUSE=0x%02h has bits outside the enabled wake sources seen (0x%02h)",
                                        v, cause_possible));
    end else if (rg == ral.PD_COUNT) begin
      int unsigned lo = 0, hi = 0;
      foreach (pd_done_t[i]) begin
        if (pd_done_t[i] <= t.t_req) lo++;
        if (pd_done_t[i] <  t.t_resp) hi++;
      end
      if (t.data[15:0] < lo[15:0] || t.data[15:0] > hi[15:0])
        fail("SB_PD_COUNT", $sformatf("PD_COUNT=%0d, model counted %0d..%0d power-downs", t.data[15:0], lo, hi));
    end
  endfunction

  protected function bit status_matches(bit [31:0] v, hist_t h);
    pmu_status_state_e s;
    case (h.st)
      PMU_RUN:   s = PMU_ST_RUN;
      PMU_IDLE:  s = PMU_ST_IDLE;
      PMU_PD:    s = PMU_ST_PD;
      PMU_SLEEP: s = PMU_ST_SLEEP;
      PMU_DEEP:  s = PMU_ST_DEEP;
      default:   s = PMU_ST_PU;
    endcase
    return (v[2:0]   == s)            &&
           (v[4]     == h.o.clk_en)    &&
           (v[5]     == h.o.iso_en)    &&
           (v[6]     == h.o.ret_en)    &&
           (v[7]     == h.o.pwr_en)    &&
           (v[8]     == h.o.pwr_good)  &&
           (v[9]     == h.o.dom_rst_n) &&
           (v[13:12] == h.o.dvfs_sel);
  endfunction

  // =========================================================================
  function void check_phase(uvm_phase phase);
    if (st inside {PMU_PD, PMU_PU})
      fail("SB_END", $sformatf("test ended in the middle of a power sequence (%s), pending steps: %0d",
                               st.name(), exp_q.size()));
    if (n_snapshots == 0) fail("SB_END", "no power-interface activity observed");
  endfunction

  function void report_phase(uvm_phase phase);
    `uvm_info("SB", $sformatf({"\n  power snapshots   : %0d\n  sequencing steps  : %0d\n",
                               "  stable transitions: %0d\n  DVFS changes      : %0d\n",
                               "  clamp checks      : %0d\n  bus transactions  : %0d (%0d error responses, %0d at a boundary)\n",
                               "  STATUS checks     : %0d\n  scoreboard errors : %0d"},
                              n_snapshots, n_seq_steps, n_transitions, n_dvfs, n_clamp_checks,
                              n_bus, n_bus_err_resp, n_boundary, n_status_checks, n_fail), UVM_LOW)
  endfunction

endclass
// ---- end env/pmu_scoreboard.svh ----

// ---- begin env/pmu_coverage.svh ----
// pmu_coverage.svh - PMU functional coverage
//
//   cg_trans : full power-state transition matrix (from x to), with the
//              transitions the PMU must never make as illegal bins
//   cg_dvfs  : DVFS operating points and every OPP-to-OPP change
//   cg_bus   : register x direction x response, error reasons, and accesses
//              to PD_CPU registers in every power state
// Register field values are covered inside the RAL (pmu_ral_pkg, cg_vals).

`uvm_analysis_imp_decl(_trans)
`uvm_analysis_imp_decl(_bus)

class pmu_coverage extends uvm_component;
  `uvm_component_utils(pmu_coverage)

  uvm_analysis_imp_trans #(pmu_trans_item, pmu_coverage) trans_imp;
  uvm_analysis_imp_bus   #(pmu_bus_item,   pmu_coverage) bus_imp;

  pmu_trans_item tr;
  pmu_bus_item   bi;

  covergroup cg_trans;
    option.per_instance = 1;
    cp_from: coverpoint tr.from_st {
      bins reset = {PMU_RESET}; bins run = {PMU_RUN}; bins idle = {PMU_IDLE};
      bins sleep = {PMU_SLEEP}; bins deep = {PMU_DEEP};
    }
    cp_to: coverpoint tr.to_st {
      bins run = {PMU_RUN}; bins idle = {PMU_IDLE}; bins sleep = {PMU_SLEEP}; bins deep = {PMU_DEEP};
    }
    x_matrix: cross cp_from, cp_to {
      // legal transitions (all must be hit)
      //   reset->run (cold boot), run->{idle,sleep,deep}, {idle,sleep,deep}->run
      illegal_bins reset_to_lp  = binsof(cp_from.reset) && !binsof(cp_to.run);
      illegal_bins lp_to_lp     = binsof(cp_from) intersect {PMU_IDLE, PMU_SLEEP, PMU_DEEP} &&
                                  binsof(cp_to)   intersect {PMU_IDLE, PMU_SLEEP, PMU_DEEP};
      ignore_bins  run_to_run   = binsof(cp_from.run) && binsof(cp_to.run);
    }
    cp_dwell: coverpoint tr.dwell_cycles iff (tr.from_st != PMU_RESET) {
      bins short_d = {[0:15]}; bins mid = {[16:127]}; bins long_d = {[128:$]};
    }
    x_from_dwell: cross cp_from, cp_dwell {
      ignore_bins reset = binsof(cp_from.reset);
      ignore_bins run   = binsof(cp_from.run);    // RUN dwell is set by register programming
    }
    cp_wake_during_pd: coverpoint tr.wake_during_pd iff (tr.to_st inside {PMU_SLEEP, PMU_DEEP}) {
      bins normal = {0}; bins early_wake = {1};
    }
    x_lp_early: cross cp_to, cp_wake_during_pd {
      ignore_bins na = binsof(cp_to) intersect {PMU_RUN, PMU_IDLE};
    }
    cp_opp_at: coverpoint tr.opp_to { bins opp[] = {[0:2]}; illegal_bins reserved = {3}; }
    x_state_opp: cross cp_to, cp_opp_at;
  endgroup

  covergroup cg_dvfs;
    option.per_instance = 1;
    cp_from: coverpoint tr.opp_from { bins opp[] = {[0:2]}; illegal_bins reserved = {3}; }
    cp_to:   coverpoint tr.opp_to   { bins opp[] = {[0:2]}; illegal_bins reserved = {3}; }
    x_change: cross cp_from, cp_to {
      ignore_bins same = (binsof(cp_from) intersect {0} && binsof(cp_to) intersect {0}) ||
                         (binsof(cp_from) intersect {1} && binsof(cp_to) intersect {1}) ||
                         (binsof(cp_from) intersect {2} && binsof(cp_to) intersect {2});
    }
  endgroup

  covergroup cg_bus;
    option.per_instance = 1;
    cp_reg: coverpoint bi.reg_idx {
      bins regs[] = {[0:11]};
      bins unmapped = {-1};
    }
    cp_kind: coverpoint bi.tr.kind;
    cp_resp: coverpoint bi.tr.resp {
      bins okay = {AXI_OKAY}; bins slverr = {AXI_SLVERR}; bins decerr = {AXI_DECERR};
      illegal_bins exokay = {AXI_EXOKAY};
    }
    cp_reason: coverpoint bi.reason;
    x_reg_kind: cross cp_reg, cp_kind;
    x_reason_kind: cross cp_reason, cp_kind {
      ignore_bins reserved_read = binsof(cp_reason) intersect {PMU_ERR_RESERVED} && binsof(cp_kind) intersect {AXI_READ};
    }
    x_reason_resp: cross cp_reason, cp_resp {
      ignore_bins impossible = (binsof(cp_reason) intersect {PMU_ERR_NONE} && !binsof(cp_resp.okay)) ||
                               (binsof(cp_reason) intersect {PMU_ERR_UNMAPPED} && !binsof(cp_resp.decerr)) ||
                               (binsof(cp_reason) intersect {PMU_ERR_RESERVED, PMU_ERR_DOMAIN_OFF} && !binsof(cp_resp.slverr));
    }
    // PD_CPU register accesses in every power state of PD_CPU
    cp_pd_state: coverpoint bi.st iff (bi.in_pd_cpu) {
      bins run = {PMU_RUN}; bins idle = {PMU_IDLE}; bins pd = {PMU_PD};
      bins sleep = {PMU_SLEEP}; bins deep = {PMU_DEEP}; bins pu = {PMU_PU};
    }
    x_pd_state_kind: cross cp_pd_state, cp_kind;
    cp_boundary: coverpoint bi.boundary iff (bi.in_pd_cpu) { bins inside_state = {0}; bins at_boundary = {1}; }
  endgroup

  function new(string name, uvm_component parent);
    super.new(name, parent);
    trans_imp = new("trans_imp", this);
    bus_imp   = new("bus_imp", this);
    cg_trans  = new();
    cg_dvfs   = new();
    cg_bus    = new();
  endfunction

  function void write_trans(pmu_trans_item t);
    tr = t;
    if (t.is_dvfs) cg_dvfs.sample();
    else           cg_trans.sample();
  endfunction

  function void write_bus(pmu_bus_item b);
    bi = b;
    cg_bus.sample();
  endfunction

  function void report_phase(uvm_phase phase);
    `uvm_info("COV", $sformatf({"\n  power-state transitions : %0.2f%%",
                                "\n    matrix %0.1f%%  dwell %0.1f%%  early-wake %0.1f%%  state x OPP %0.1f%%",
                                "\n  DVFS                    : %0.2f%%",
                                "\n  bus / error responses   : %0.2f%%",
                                "\n    reg x dir %0.1f%%  reason x dir %0.1f%%  reason x resp %0.1f%%  PD_CPU state x dir %0.1f%%  boundary %0.1f%%"},
                               cg_trans.get_inst_coverage(),
                               cg_trans.x_matrix.get_inst_coverage(), cg_trans.x_from_dwell.get_inst_coverage(),
                               cg_trans.x_lp_early.get_inst_coverage(), cg_trans.x_state_opp.get_inst_coverage(),
                               cg_dvfs.get_inst_coverage(),
                               cg_bus.get_inst_coverage(),
                               cg_bus.x_reg_kind.get_inst_coverage(), cg_bus.x_reason_kind.get_inst_coverage(),
                               cg_bus.x_reason_resp.get_inst_coverage(), cg_bus.x_pd_state_kind.get_inst_coverage(),
                               cg_bus.cp_boundary.get_inst_coverage()), UVM_LOW)
  endfunction

endclass
// ---- end env/pmu_coverage.svh ----

// ---- begin env/pmu_virtual_sequencer.svh ----
// pmu_virtual_sequencer.svh
class pmu_virtual_sequencer extends uvm_sequencer;
  `uvm_component_utils(pmu_virtual_sequencer)

  axi_lite_sequencer axi_sqr;
  pwr_sequencer      pwr_sqr;
  pmu_reg_block      ral;
  pmu_env_cfg        cfg;
  pmu_state_tracker  tracker;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction
endclass
// ---- end env/pmu_virtual_sequencer.svh ----

// ---- begin env/pmu_env.svh ----
// pmu_env.svh - PMU subsystem environment
class pmu_env extends uvm_env;
  `uvm_component_utils(pmu_env)

  pmu_env_cfg               cfg;
  axi_lite_agent            axi;
  pwr_agent                 pwr;
  pmu_reg_block             ral;
  uvm_reg_predictor #(axi_lite_item) predictor;
  axi_lite_reg_adapter      adapter;
  pmu_scoreboard            sb;
  pmu_coverage              cov;
  pmu_virtual_sequencer     vsqr;
  pmu_state_tracker         tracker;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(pmu_env_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("CFG", "pmu_env: no pmu_env_cfg")

    // Register model
    if (cfg.ral == null) begin
      if (cfg.has_coverage) uvm_reg::include_coverage("*", UVM_CVR_FIELD_VALS);
      cfg.ral = pmu_reg_block::type_id::create("ral");
      cfg.ral.configure(null, "");
      cfg.ral.build(cfg.base_addr);
      cfg.ral.reset();
      if (cfg.has_coverage) void'(cfg.ral.set_coverage(UVM_CVR_FIELD_VALS));
    end
    ral = cfg.ral;
    // check_on_read masks volatile fields out of the compare but still calls
    // get_mirrored_value() on them, which warns once per field per read.
    uvm_root::get().set_report_id_action("UVM/FLD/GET_MIRRORED_VAL/VOL", UVM_NO_ACTION);
    // The predictor warns for every error response; those are checked by the
    // scoreboard (and are intentional in the error tests).
    uvm_root::get().set_report_id_action("PREDICT_NOK", UVM_NO_ACTION);

    axi = axi_lite_agent::type_id::create("axi", this);
    axi.cfg = cfg.axi_cfg;
    pwr = pwr_agent::type_id::create("pwr", this);
    pwr.cfg = cfg.pwr_cfg_h;

    adapter   = axi_lite_reg_adapter::type_id::create("adapter");
    predictor = uvm_reg_predictor#(axi_lite_item)::type_id::create("predictor", this);

    tracker = pmu_state_tracker::type_id::create("tracker");

    if (cfg.has_scoreboard) begin
      sb = pmu_scoreboard::type_id::create("sb", this);
      sb.cfg = cfg;
      sb.ral = ral;
      sb.tracker = tracker;
    end
    if (cfg.has_coverage) cov = pmu_coverage::type_id::create("cov", this);

    vsqr = pmu_virtual_sequencer::type_id::create("vsqr", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    tracker.vif = cfg.pwr_cfg_h.vif;

    // RAL frontdoor through the AXI4-Lite agent, explicit prediction from the monitor
    if (cfg.axi_cfg.is_active == UVM_ACTIVE) ral.default_map.set_sequencer(axi.sqr, adapter);
    ral.default_map.set_auto_predict(0);
    ral.default_map.set_check_on_read(1);
    // PD_CPU register data is checked by the scoreboard (it models power loss)
    ral.CPU_WIN.default_map.set_check_on_read(0);
    predictor.map     = ral.default_map;
    predictor.adapter = adapter;
    axi.ap.connect(predictor.bus_in);

    if (cfg.has_scoreboard) begin
      axi.ap.connect(sb.axi_imp);
      pwr.ap.connect(sb.pwr_imp);
      if (cfg.has_coverage) begin
        sb.trans_ap.connect(cov.trans_imp);
        sb.bus_ap.connect(cov.bus_imp);
      end
    end

    vsqr.axi_sqr = axi.sqr;
    vsqr.pwr_sqr = pwr.sqr;
    vsqr.ral     = ral;
    vsqr.cfg     = cfg;
    vsqr.tracker = tracker;
  endfunction

endclass
// ---- end env/pmu_env.svh ----

// ---- begin env/pmu_vseq_lib.svh ----
// pmu_vseq_lib.svh - PMU virtual sequence library
//
// Power-state transitions (one sequence per transition, plus DVFS):
//   pmu_pwr_trans_vseq     generic: RUN -> {IDLE|SLEEP|DEEP_SLEEP} -> RUN
//   pmu_idle_vseq          RUN -> IDLE -> RUN
//   pmu_sleep_vseq         RUN -> SLEEP -> RUN
//   pmu_deep_sleep_vseq    RUN -> DEEP_SLEEP -> RUN
//   pmu_wake_during_pd_vseq  wake request while the power-down sequence runs
//   pmu_dvfs_vseq          OPP change in IDLE (any OPP -> any other OPP)
//   pmu_pwr_matrix_vseq    every transition and every OPP pair, deterministic
//   pmu_pwr_rand_vseq      N random transitions / DVFS changes
// Bus traffic and registers:
//   pmu_bus_traffic_vseq   background reads/writes incl. PD_CPU registers
//   pmu_reg_rand_vseq      random register accesses through the RAL and raw AXI
//   pmu_ral_builtin_vseq   uvm_reg_hw_reset_seq + uvm_reg_bit_bash_seq
//   pmu_err_vseq           DECERR / SLVERR (reserved value, PD_CPU off) injection

typedef enum { PMU_TGT_IDLE, PMU_TGT_SLEEP, PMU_TGT_DEEP } pmu_lp_target_e;

// =============================================================================
class pmu_base_vseq extends uvm_sequence;
  `uvm_object_utils(pmu_base_vseq)
  `uvm_declare_p_sequencer(pmu_virtual_sequencer)

  pmu_reg_block     ral;
  pmu_env_cfg       cfg;
  pmu_state_tracker trk;

  function new(string name = "pmu_base_vseq");
    super.new(name);
  endfunction

  function void init();
    ral = p_sequencer.ral;
    cfg = p_sequencer.cfg;
    trk = p_sequencer.tracker;
  endfunction

  task cycles(int unsigned n);
    repeat (n) @(posedge trk.vif.clk);
  endtask

  task wait_state(pmu_state_e s, string ctx = "");
    bit ok;
    trk.wait_for(s, cfg.state_timeout, ok);
    if (!ok) `uvm_error("VSEQ", $sformatf("%s: timeout waiting for %s (model is in %s)", ctx, s.name(), trk.cur.name()))
  endtask

  task reg_write(uvm_reg rg, uvm_reg_data_t v, bit expect_ok = 1);
    uvm_status_e st;
    rg.write(st, v, .parent(this));
    if (expect_ok && st != UVM_IS_OK)
      `uvm_error("VSEQ", $sformatf("write %s=0x%0h failed", rg.get_name(), v))
    if (!expect_ok && st == UVM_IS_OK)
      `uvm_error("VSEQ", $sformatf("write %s=0x%0h unexpectedly succeeded", rg.get_name(), v))
  endtask

  task reg_read(uvm_reg rg, output uvm_reg_data_t v, input bit expect_ok = 1);
    uvm_status_e st;
    rg.read(st, v, .parent(this));
    if (expect_ok && st != UVM_IS_OK)
      `uvm_error("VSEQ", $sformatf("read %s failed", rg.get_name()))
  endtask

  task cpu_wfi();
    pwr_wfi_seq s = pwr_wfi_seq::type_id::create("wfi");
    if (!s.randomize()) `uvm_fatal("VSEQ", "randomize failed")
    s.start(p_sequencer.pwr_sqr, this);
  endtask

  task wake(bit [`PWR_IRQ_W-1:0] irq);
    pwr_wake_seq s = pwr_wake_seq::type_id::create("wake");
    if (!s.randomize() with { irq == local::irq; }) `uvm_fatal("VSEQ", "randomize failed")
    s.start(p_sequencer.pwr_sqr, this);
  endtask

  task irq_pulse(bit [`PWR_IRQ_W-1:0] irq);
    pwr_irq_pulse_seq s = pwr_irq_pulse_seq::type_id::create("pulse");
    if (!s.randomize() with { irq == local::irq; }) `uvm_fatal("VSEQ", "randomize failed")
    s.start(p_sequencer.pwr_sqr, this);
  endtask

  // Raw AXI access (bypasses the RAL; prediction still happens via the monitor)
  task axi_write(bit [31:0] addr, bit [31:0] data, output axi_lite_resp_e r,
                 input bit [3:0] strb = 4'hF, input axi_lite_dly_e dly = AXI_DLY_RANDOM);
    axi_lite_base_seq s = axi_lite_base_seq::type_id::create("aw");
    s.dly_mode = dly;
    s.set_sequencer(p_sequencer.axi_sqr);
    s.set_parent_sequence(this);
    s.write(addr, data, r, strb);
  endtask

  task axi_read(bit [31:0] addr, output bit [31:0] data, output axi_lite_resp_e r,
                input axi_lite_dly_e dly = AXI_DLY_RANDOM);
    axi_lite_base_seq s = axi_lite_base_seq::type_id::create("ar");
    s.dly_mode = dly;
    s.set_sequencer(p_sequencer.axi_sqr);
    s.set_parent_sequence(this);
    s.read(addr, data, r);
  endtask

  function bit [31:0] reg_addr(uvm_reg rg);
    return rg.get_address(ral.default_map);
  endfunction

endclass

// =============================================================================
// Generic low-power round trip: RUN -> target -> RUN
class pmu_pwr_trans_vseq extends pmu_base_vseq;
  `uvm_object_utils(pmu_pwr_trans_vseq)

  rand pmu_lp_target_e         target;
  rand bit                     change_dvfs;   // program a new OPP before WFI
  rand bit [1:0]               opp;
  rand int unsigned            dwell;         // cycles spent in the low-power state
  rand bit                     wake_early;    // wake while power-down is in progress
  rand bit [`PWR_IRQ_W-1:0]    mask;
  rand bit [`PWR_IRQ_W-1:0]    wake_irq;
  rand bit                     masked_noise;  // pulse disabled wake sources first
  rand bit                     idle_ret;      // IDLE with RET_EN=1 (must still be IDLE)
  rand bit                     set_delay;
  rand bit [7:0]               seq_delay;

  constraint c_opp    { opp < PMU_N_OPP; }
  constraint c_mask   { mask != 0; (wake_irq & mask) != 0; $countones(wake_irq) <= 3;
                        mask dist { 8'hFF := 3, [8'h01:8'hFE] :/ 7 }; }
  constraint c_early  { (target == PMU_TGT_IDLE) -> !wake_early; wake_early dist { 0 := 4, 1 := 1 }; }
  constraint c_dwell  { dwell dist { [0:10] := 3, [11:100] := 4, [101:400] := 2 }; }
  constraint c_ret    { (target != PMU_TGT_IDLE) -> !idle_ret; }
  constraint c_delay  { seq_delay inside {[1:8]}; set_delay dist { 0 := 3, 1 := 1 }; }
  constraint c_dvfs   { change_dvfs dist { 0 := 2, 1 := 1 }; }

  function new(string name = "pmu_pwr_trans_vseq");
    super.new(name);
  endfunction

  function pmu_state_e target_state();
    case (target)
      PMU_TGT_IDLE:  return PMU_IDLE;
      PMU_TGT_SLEEP: return PMU_SLEEP;
      default:       return PMU_DEEP;
    endcase
  endfunction

  task body();
    bit [1:0] ctrl;
    init();
    wait_state(PMU_RUN, get_name());
    `uvm_info("VSEQ", $sformatf("RUN -> %s -> RUN (dvfs=%0b opp=%0d dwell=%0d early_wake=%0b mask=0x%02h irq=0x%02h)",
                                target_state().name(), change_dvfs, opp, dwell, wake_early, mask, wake_irq), UVM_MEDIUM)
    if (set_delay)   reg_write(ral.SEQ_DELAY, seq_delay);
    reg_write(ral.WAKE_MASK, mask);
    if (change_dvfs) reg_write(ral.DVFS, opp);
    case (target)
      PMU_TGT_IDLE:  ctrl = idle_ret ? 2'b10 : 2'b00;   // {RET_EN, PD_EN}
      PMU_TGT_SLEEP: ctrl = 2'b01;
      default:       ctrl = 2'b11;
    endcase
    reg_write(ral.CTRL, ctrl);

    cpu_wfi();
    if (wake_early) begin
      wait_state(PMU_PD, get_name());
      wake(wake_irq);
      wait_state(target_state(), get_name());
    end else begin
      wait_state(target_state(), get_name());
      if (masked_noise && (~mask != 0)) irq_pulse(~mask & 8'($urandom | 1 << $urandom_range(7)));
      cycles(dwell);
      wake(wake_irq);
    end
    wait_state(PMU_RUN, get_name());
  endtask
endclass

class pmu_idle_vseq extends pmu_pwr_trans_vseq;
  `uvm_object_utils(pmu_idle_vseq)
  constraint c_tgt { target == PMU_TGT_IDLE; }
  function new(string name = "pmu_idle_vseq"); super.new(name); endfunction
endclass

class pmu_sleep_vseq extends pmu_pwr_trans_vseq;
  `uvm_object_utils(pmu_sleep_vseq)
  constraint c_tgt { target == PMU_TGT_SLEEP; }
  function new(string name = "pmu_sleep_vseq"); super.new(name); endfunction
endclass

class pmu_deep_sleep_vseq extends pmu_pwr_trans_vseq;
  `uvm_object_utils(pmu_deep_sleep_vseq)
  constraint c_tgt { target == PMU_TGT_DEEP; }
  function new(string name = "pmu_deep_sleep_vseq"); super.new(name); endfunction
endclass

class pmu_wake_during_pd_vseq extends pmu_pwr_trans_vseq;
  `uvm_object_utils(pmu_wake_during_pd_vseq)
  constraint c_tgt { target != PMU_TGT_IDLE; wake_early == 1; }
  function new(string name = "pmu_wake_during_pd_vseq"); super.new(name); endfunction
endclass

// DVFS: move to a different OPP through IDLE
class pmu_dvfs_vseq extends pmu_pwr_trans_vseq;
  `uvm_object_utils(pmu_dvfs_vseq)
  int to_opp = -1;   // >= 0: force this OPP
  constraint c_tgt { target == PMU_TGT_IDLE; change_dvfs == 1; }
  function new(string name = "pmu_dvfs_vseq"); super.new(name); endfunction
  task body();
    init();
    if (to_opp >= 0) opp = to_opp[1:0];
    else if (opp == trk.opp) opp = (trk.opp + 1) % PMU_N_OPP;
    super.body();
    if (trk.opp != opp)
      `uvm_error("VSEQ", $sformatf("DVFS: still at OPP%0d after IDLE, programmed OPP%0d", trk.opp, opp))
  endtask
endclass

// =============================================================================
// Deterministic walk of the full transition matrix and all OPP pairs
class pmu_pwr_matrix_vseq extends pmu_base_vseq;
  `uvm_object_utils(pmu_pwr_matrix_vseq)
  function new(string name = "pmu_pwr_matrix_vseq"); super.new(name); endfunction

  task body();
    int unsigned dwells[3] = '{2, 50, 300};
    int          opps[6]   = '{1, 2, 0, 2, 1, 0};   // 0->1->2->0->2->1->0
    init();
    // Every low-power state, three dwell lengths, normal and early wake
    foreach (dwells[d]) begin
      for (int t = 0; t < 3; t++) begin
        pmu_pwr_trans_vseq s = pmu_pwr_trans_vseq::type_id::create($sformatf("m_%0d_%0d", t, d));
        if (!s.randomize() with { target == pmu_lp_target_e'(t); dwell == dwells[d];
                                  wake_early == 0; change_dvfs == 0; })
          `uvm_fatal("VSEQ", "randomize failed")
        s.start(p_sequencer, this);
      end
    end
    for (int t = 1; t < 3; t++) begin
      pmu_pwr_trans_vseq s = pmu_pwr_trans_vseq::type_id::create($sformatf("early_%0d", t));
      if (!s.randomize() with { target == pmu_lp_target_e'(t); wake_early == 1; change_dvfs == 0; })
        `uvm_fatal("VSEQ", "randomize failed")
      s.start(p_sequencer, this);
    end
    // IDLE entered with RET_EN=1 but PD_EN=0 must remain IDLE
    begin
      pmu_idle_vseq s = pmu_idle_vseq::type_id::create("idle_ret");
      if (!s.randomize() with { idle_ret == 1; change_dvfs == 0; }) `uvm_fatal("VSEQ", "randomize failed")
      s.start(p_sequencer, this);
    end
    // Every OPP -> OPP change
    foreach (opps[i]) begin
      pmu_dvfs_vseq s = pmu_dvfs_vseq::type_id::create($sformatf("dvfs_%0d", i));
      if (!s.randomize() with { wake_early == 0; }) `uvm_fatal("VSEQ", "randomize failed")
      s.to_opp = opps[i];
      s.start(p_sequencer, this);
    end
    // A DVFS target written before SLEEP stays pending until the next IDLE
    begin
      pmu_sleep_vseq s = pmu_sleep_vseq::type_id::create("dvfs_before_sleep");
      if (!s.randomize() with { change_dvfs == 1; opp == 1; }) `uvm_fatal("VSEQ", "randomize failed")
      s.start(p_sequencer, this);
    end
    begin
      pmu_dvfs_vseq s = pmu_dvfs_vseq::type_id::create("dvfs_after_sleep");
      if (!s.randomize()) `uvm_fatal("VSEQ", "randomize failed")
      s.to_opp = 0;
      s.start(p_sequencer, this);
    end
  endtask
endclass

// =============================================================================
class pmu_pwr_rand_vseq extends pmu_base_vseq;
  `uvm_object_utils(pmu_pwr_rand_vseq)
  rand int unsigned n;
  constraint c_n { n inside {[10:30]}; }
  function new(string name = "pmu_pwr_rand_vseq"); super.new(name); endfunction
  task body();
    init();
    for (int i = 0; i < n; i++) begin
      pmu_pwr_trans_vseq s;
      if ($urandom_range(4) == 0) begin
        pmu_dvfs_vseq d = pmu_dvfs_vseq::type_id::create($sformatf("rnd_dvfs_%0d", i));
        s = d;
      end else begin
        s = pmu_pwr_trans_vseq::type_id::create($sformatf("rnd_%0d", i));
      end
      if (!s.randomize()) `uvm_fatal("VSEQ", "randomize failed")
      s.start(p_sequencer, this);
    end
  endtask
endclass

// =============================================================================
// Background bus traffic, safe to run during power transitions: reads of every
// register, writes only to PD_CPU registers and WAKE_CAUSE (W1C), occasional
// unmapped accesses. Runs until `stop` is set.
class pmu_bus_traffic_vseq extends pmu_base_vseq;
  `uvm_object_utils(pmu_bus_traffic_vseq)
  bit          stop;
  int unsigned n_done;
  function new(string name = "pmu_bus_traffic_vseq"); super.new(name); endfunction

  task body();
    uvm_reg regs[$], win[$];
    init();
    ral.get_registers(regs);
    ral.CPU_WIN.get_registers(win);
    while (!stop) begin
      axi_lite_resp_e r;
      bit [31:0]      d;
      axi_lite_dly_e  dly = axi_lite_dly_e'($urandom_range(2));
      int unsigned    k   = $urandom_range(99);
      if (k < 45) begin
        axi_read(reg_addr(regs[$urandom_range(regs.size() - 1)]), d, r, dly);
      end else if (k < 85) begin
        axi_write(reg_addr(win[$urandom_range(win.size() - 1)]), $urandom, r,
                  ($urandom_range(3) == 0) ? 4'($urandom) : 4'hF, dly);
      end else if (k < 92) begin
        axi_write(reg_addr(ral.WAKE_CAUSE), $urandom, r, 4'hF, dly);
      end else begin
        bit [31:0] a = cfg.base_addr + 32'h20 + 4 * $urandom_range(30);   // 0x20..0x98 unmapped
        if ($urandom_range(1)) axi_read(a, d, r, dly); else axi_write(a, $urandom, r, 4'hF, dly);
      end
      n_done++;
      cycles($urandom_range(6));
    end
  endtask
endclass

// =============================================================================
// Random register accesses (domain kept in RUN)
class pmu_reg_rand_vseq extends pmu_base_vseq;
  `uvm_object_utils(pmu_reg_rand_vseq)
  rand int unsigned n;
  constraint c_n { n inside {[100:300]}; }
  function new(string name = "pmu_reg_rand_vseq"); super.new(name); endfunction

  task body();
    uvm_reg rw_regs[$], all[$];
    init();
    wait_state(PMU_RUN, get_name());
    ral.get_registers(all);
    rw_regs = '{ral.CTRL, ral.DVFS, ral.WAKE_MASK, ral.SEQ_DELAY,
                ral.CPU_WIN.SCRATCH[0], ral.CPU_WIN.SCRATCH[1], ral.CPU_WIN.SCRATCH[2], ral.CPU_WIN.SCRATCH[3]};
    for (int i = 0; i < n; i++) begin
      uvm_reg         rg = rw_regs[$urandom_range(rw_regs.size() - 1)];
      uvm_reg_data_t  v;
      uvm_status_e    st;
      axi_lite_resp_e r;
      bit [31:0]      d;
      case ($urandom_range(5))
        0, 1: begin   // RAL write of a constrained-random value, then read back
          // Retry until the register's own constraints hold. Verilator 5.054
          // was observed to ignore pmu_reg_dvfs::c_legal when the RAL field
          // covergroups are built; on a compliant simulator this loop exits
          // after the first randomize().
          repeat (16) begin
            if (!rg.randomize()) `uvm_fatal("VSEQ", "reg randomize failed")
            if (rg != ral.DVFS || ral.DVFS.OPP.get() < PMU_N_OPP) break;
          end
          if (rg == ral.DVFS && ral.DVFS.OPP.get() >= PMU_N_OPP) void'(ral.DVFS.OPP.randomize() with { value < PMU_N_OPP; });
          reg_write(rg, rg.get());
          reg_read(rg, v);
        end
        2: begin      // RAL mirror with check (PD_AON registers)
          uvm_reg any = all[$urandom_range(all.size() - 1)];
          if (!ral.in_pd_cpu(any)) any.mirror(st, UVM_CHECK, .parent(this));
          else                     reg_read(any, v);
        end
        3: begin      // raw write with random data and byte strobes (reserved values included)
          axi_write(reg_addr(rg), $urandom, r, 4'($urandom), axi_lite_dly_e'($urandom_range(3)));
          axi_read(reg_addr(rg), d, r);
        end
        4: begin      // back-to-back burst over all registers
          axi_lite_b2b_seq b = axi_lite_b2b_seq::type_id::create("b2b");
          foreach (all[j]) if (all[j] != ral.CTRL && all[j] != ral.DVFS) b.addrs.push_back(reg_addr(all[j]));
          if (!b.randomize() with { mode inside {axi_lite_b2b_seq::B2B_READS, axi_lite_b2b_seq::B2B_ALTERNATE,
                                                 axi_lite_b2b_seq::B2B_WR_THEN_RD}; })
            `uvm_fatal("VSEQ", "randomize failed")
          b.start(p_sequencer.axi_sqr, this);
        end
        default: begin // read every register
          foreach (all[j]) begin
            axi_read(reg_addr(all[j]), d, r, AXI_DLY_ZERO);
          end
        end
      endcase
    end
    // Leave the DUT in a known state for anything that follows
    reg_write(ral.CTRL, 0);
    reg_write(ral.WAKE_MASK, 8'hFF);
    reg_write(ral.SEQ_DELAY, 4);
  endtask
endclass

// =============================================================================
class pmu_ral_builtin_vseq extends pmu_base_vseq;
  `uvm_object_utils(pmu_ral_builtin_vseq)
  bit do_hw_reset = 1;
  bit do_bit_bash = 1;
  function new(string name = "pmu_ral_builtin_vseq"); super.new(name); endfunction
  task body();
    init();
    wait_state(PMU_RUN, get_name());
    if (do_hw_reset) begin
      uvm_reg_hw_reset_seq s = uvm_reg_hw_reset_seq::type_id::create("hw_reset");
      s.model = ral;
      `uvm_info("VSEQ", "running uvm_reg_hw_reset_seq", UVM_LOW)
      s.start(null, this);
    end
    if (do_bit_bash) begin
      uvm_reg_bit_bash_seq s = uvm_reg_bit_bash_seq::type_id::create("bit_bash");
      s.model = ral;
      `uvm_info("VSEQ", "running uvm_reg_bit_bash_seq", UVM_LOW)
      s.start(null, this);
    end
  endtask
endclass

// =============================================================================
// Error injection: every way to get an error response from the PMU
class pmu_err_vseq extends pmu_base_vseq;
  `uvm_object_utils(pmu_err_vseq)
  int unsigned n_okay, n_slverr, n_decerr;
  function new(string name = "pmu_err_vseq"); super.new(name); endfunction

  protected function void count(axi_lite_resp_e r);
    case (r)
      AXI_OKAY:   n_okay++;
      AXI_SLVERR: n_slverr++;
      AXI_DECERR: n_decerr++;
      default: ;
    endcase
  endfunction

  // Hammer the PD_CPU registers with reads and writes
  task hammer_win(int unsigned n);
    uvm_reg win[$];
    axi_lite_resp_e r;
    bit [31:0] d;
    ral.CPU_WIN.get_registers(win);
    repeat (n) begin
      bit [31:0] a = reg_addr(win[$urandom_range(win.size() - 1)]);
      if ($urandom_range(1)) axi_write(a, $urandom, r, 4'hF, AXI_DLY_ZERO);
      else                   axi_read(a, d, r, AXI_DLY_ZERO);
      count(r);
    end
  endtask

  task body();
    axi_lite_err_seq unm;
    axi_lite_resp_e  r;
    bit [31:0]       d;
    init();
    wait_state(PMU_RUN, get_name());

    // 1. Unmapped addresses -> DECERR
    unm = axi_lite_err_seq::type_id::create("unmapped");
    unm.addrs = '{cfg.base_addr + 32'h020, cfg.base_addr + 32'h0FC, cfg.base_addr + 32'h110,
                  cfg.base_addr + 32'h200, cfg.base_addr + 32'hFFC, cfg.base_addr + 32'h1000,
                  32'h8000_0000, 32'hFFFF_FFFC};
    unm.reps = 3;
    unm.dly_mode = AXI_DLY_RANDOM;
    unm.start(p_sequencer.axi_sqr, this);
    n_okay += unm.n_okay; n_slverr += unm.n_slverr; n_decerr += unm.n_decerr;

    // 2. Reserved DVFS operating point -> SLVERR, register unchanged
    axi_write(reg_addr(ral.DVFS), 32'h3, r);                  count(r);
    axi_write(reg_addr(ral.DVFS), 32'hFFFF_FFFF, r);          count(r);
    axi_write(reg_addr(ral.DVFS), 32'h3, r, 4'b1110);         count(r);   // lane 0 not written: OKAY
    reg_write(ral.DVFS, 3, .expect_ok(0));
    axi_read(reg_addr(ral.DVFS), d, r);                       count(r);   // predictor checks unchanged

    // 3. PD_CPU registers while PD_CPU is not running -> SLVERR
    hammer_win(4);                                            // RUN: OKAY
    for (int t = 0; t < 3; t++) begin
      pmu_pwr_trans_vseq      s = pmu_pwr_trans_vseq::type_id::create($sformatf("err_lp_%0d", t));
      pmu_bus_traffic_vseq    bg = pmu_bus_traffic_vseq::type_id::create("bg");
      if (!s.randomize() with { target == pmu_lp_target_e'(t); dwell inside {[150:300]};
                                wake_early == 0; change_dvfs == 0; })
        `uvm_fatal("VSEQ", "randomize failed")
      fork
        s.start(p_sequencer, this);
        begin
          wait_state(s.target_state(), "err");
          hammer_win(10);
        end
        begin
          // traffic across the PD / PU boundaries as well
          bit ok;
          fork bg.start(p_sequencer, this); join_none
          trk.wait_leave(PMU_RUN, cfg.state_timeout, ok);
          trk.wait_for(PMU_RUN, cfg.state_timeout, ok);
          bg.stop = 1;
        end
      join
      wait fork;
      hammer_win(4);                                          // back in RUN: OKAY, reset values
    end

    `uvm_info("VSEQ", $sformatf("error injection responses: OKAY=%0d SLVERR=%0d DECERR=%0d",
                                n_okay, n_slverr, n_decerr), UVM_LOW)
    if (n_decerr == 0) `uvm_error("VSEQ", "no DECERR was provoked")
    if (n_slverr == 0) `uvm_error("VSEQ", "no SLVERR was provoked")
  endtask
endclass
// ---- end env/pmu_vseq_lib.svh ----

endpackage
// ---- end env/pmu_env_pkg.sv ----

// ---- begin tests/pmu_test_pkg.sv ----
// -----------------------------------------------------------------------------
// pmu_test_pkg.sv - PMU UVM tests
//
//   pmu_smoke_test        cold boot, ID/scratch access, one IDLE and one SLEEP
//   pmu_ral_test          uvm_reg_hw_reset_seq + uvm_reg_bit_bash_seq
//   pmu_rand_reg_test     random register traffic (RAL + raw AXI, strobes, b2b)
//   pmu_rand_pwr_test     random power transitions + DVFS mixed with bus traffic
//   pmu_pwr_matrix_test   deterministic full transition matrix + all OPP pairs
//   pmu_err_test          DECERR / SLVERR injection, PD_CPU accessed while off
//   pmu_full_test         everything above in one run (coverage closure)
//
// Plusargs:  +UVM_TESTNAME=<test>  +PMU_ITERS=<n>  +PMU_BASE=<hex>
// Seed:      simulator option (see scripts/), e.g. xrun -svseed, vsim -sv_seed,
//            vcs +ntb_random_seed, verilator +verilator+seed+
// -----------------------------------------------------------------------------
package pmu_test_pkg;

  import uvm_pkg::*;
  `include "uvm_macros.svh"
  import axi_lite_pkg::*;
  import pwr_pkg::*;
  import pmu_ral_pkg::*;
  import pmu_env_pkg::*;

  class pmu_base_test extends uvm_test;
    `uvm_component_utils(pmu_base_test)

    pmu_env     env;
    pmu_env_cfg cfg;
    int unsigned iters = 0;     // 0: test default

    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
      string s;
      super.build_phase(phase);
      cfg = pmu_env_cfg::type_id::create("cfg");
      if (!uvm_config_db#(virtual axi_lite_if)::get(this, "", "axi_vif", cfg.axi_cfg.vif))
        `uvm_fatal("CFG", "axi_vif not in config_db")
      if (!uvm_config_db#(virtual pwr_if)::get(this, "", "pwr_vif", cfg.pwr_cfg_h.vif))
        `uvm_fatal("CFG", "pwr_vif not in config_db")
      void'(uvm_config_db#(bit [`PWR_ISO_W-1:0])::get(this, "", "iso_clamp", cfg.iso_clamp));
      if ($value$plusargs("PMU_BASE=%h", cfg.base_addr)) ;
      if ($value$plusargs("PMU_ITERS=%d", iters)) ;
      configure(cfg);
      uvm_config_db#(pmu_env_cfg)::set(this, "env", "cfg", cfg);
      env = pmu_env::type_id::create("env", this);
    endfunction

    // Hook for derived tests
    virtual function void configure(pmu_env_cfg c);
    endfunction

    function void end_of_elaboration_phase(uvm_phase phase);
      if (uvm_report_enabled(UVM_HIGH)) uvm_root::get().print_topology();
    endfunction

    task run_phase(uvm_phase phase);
      bit ok;
      phase.raise_objection(this);
      phase.get_objection().set_drain_time(this, 200ns);
      // cold boot: PMU must bring PD_CPU up after PD_AON reset
      env.tracker.wait_for(PMU_RUN, 5000, ok);
      if (!ok) `uvm_fatal("TEST", "PD_CPU did not reach RUN after reset (cold boot)")
      main();
      phase.drop_objection(this);
    endtask

    virtual task main();
    endtask

    // Start a virtual sequence on the environment's virtual sequencer
    task run_vseq(pmu_base_vseq s);
      s.start(env.vsqr);
    endtask

    function void report_phase(uvm_phase phase);
      uvm_report_server rs = uvm_report_server::get_server();
      int n_err = rs.get_severity_count(UVM_ERROR) + rs.get_severity_count(UVM_FATAL);
      if (n_err == 0)
        `uvm_info("TEST", $sformatf("*** TEST PASSED *** %s", get_type_name()), UVM_NONE)
      else
        `uvm_info("TEST", $sformatf("*** TEST FAILED *** %s (%0d errors)", get_type_name(), n_err), UVM_NONE)
    endfunction
  endclass

  // ---------------------------------------------------------------------------
  class pmu_smoke_test extends pmu_base_test;
    `uvm_component_utils(pmu_smoke_test)
    function new(string name, uvm_component parent); super.new(name, parent); endfunction

    task main();
      pmu_base_vseq   b = pmu_base_vseq::type_id::create("b");
      pmu_idle_vseq   i = pmu_idle_vseq::type_id::create("idle");
      pmu_sleep_vseq  s = pmu_sleep_vseq::type_id::create("sleep");
      uvm_reg_data_t  v;
      uvm_status_e    st;
      b.set_sequencer(env.vsqr);
      b.init();
      env.ral.ID.mirror(st, UVM_CHECK);
      if (st != UVM_IS_OK) `uvm_error("TEST", "ID read failed")
      b.reg_write(env.ral.CPU_WIN.SCRATCH[0], 32'hCAFE_F00D);
      b.reg_read(env.ral.CPU_WIN.SCRATCH[0], v);
      if (v != 32'hCAFE_F00D) `uvm_error("TEST", $sformatf("SCRATCH0 read 0x%08h", v))
      if (!i.randomize() with { change_dvfs == 0; }) `uvm_fatal("TEST", "randomize failed")
      run_vseq(i);
      if (!s.randomize() with { wake_early == 0; dwell < 50; }) `uvm_fatal("TEST", "randomize failed")
      run_vseq(s);
      // PD_CPU registers are not retained across SLEEP (scoreboard checks 0)
      b.reg_read(env.ral.CPU_WIN.SCRATCH[0], v);
      env.ral.STATUS.mirror(st, UVM_NO_CHECK);
    endtask
  endclass

  // ---------------------------------------------------------------------------
  class pmu_ral_test extends pmu_base_test;
    `uvm_component_utils(pmu_ral_test)
    function new(string name, uvm_component parent); super.new(name, parent); endfunction
    task main();
      pmu_ral_builtin_vseq s = pmu_ral_builtin_vseq::type_id::create("ral");
      string which;
      if ($value$plusargs("RAL_SEQ=%s", which)) begin
        s.do_hw_reset = (which == "hw_reset" || which == "all");
        s.do_bit_bash = (which == "bit_bash" || which == "all");
      end
      run_vseq(s);
    endtask
  endclass

  // ---------------------------------------------------------------------------
  class pmu_rand_reg_test extends pmu_base_test;
    `uvm_component_utils(pmu_rand_reg_test)
    function new(string name, uvm_component parent); super.new(name, parent); endfunction
    task main();
      pmu_reg_rand_vseq s = pmu_reg_rand_vseq::type_id::create("reg_rand");
      if (!s.randomize() with { (local::iters != 0) -> n == local::iters; }) `uvm_fatal("TEST", "randomize failed")
      run_vseq(s);
    endtask
  endclass

  // ---------------------------------------------------------------------------
  class pmu_rand_pwr_test extends pmu_base_test;
    `uvm_component_utils(pmu_rand_pwr_test)
    function new(string name, uvm_component parent); super.new(name, parent); endfunction
    task main();
      pmu_pwr_rand_vseq    p  = pmu_pwr_rand_vseq::type_id::create("pwr_rand");
      pmu_bus_traffic_vseq bg = pmu_bus_traffic_vseq::type_id::create("traffic");
      if (!p.randomize() with { (local::iters != 0) -> n == local::iters; }) `uvm_fatal("TEST", "randomize failed")
      fork
        bg.start(env.vsqr);
        begin
          run_vseq(p);
          bg.stop = 1;
        end
      join
      `uvm_info("TEST", $sformatf("%0d background bus transactions", bg.n_done), UVM_LOW)
    endtask
  endclass

  // ---------------------------------------------------------------------------
  class pmu_pwr_matrix_test extends pmu_base_test;
    `uvm_component_utils(pmu_pwr_matrix_test)
    function new(string name, uvm_component parent); super.new(name, parent); endfunction
    task main();
      pmu_pwr_matrix_vseq s = pmu_pwr_matrix_vseq::type_id::create("matrix");
      run_vseq(s);
    endtask
  endclass

  // ---------------------------------------------------------------------------
  class pmu_err_test extends pmu_base_test;
    `uvm_component_utils(pmu_err_test)
    function new(string name, uvm_component parent); super.new(name, parent); endfunction
    task main();
      pmu_err_vseq s = pmu_err_vseq::type_id::create("err");
      run_vseq(s);
    endtask
  endclass

  // ---------------------------------------------------------------------------
  class pmu_full_test extends pmu_base_test;
    `uvm_component_utils(pmu_full_test)
    function new(string name, uvm_component parent); super.new(name, parent); endfunction
    task main();
      pmu_ral_builtin_vseq ral_s = pmu_ral_builtin_vseq::type_id::create("ral");
      pmu_reg_rand_vseq    reg_s = pmu_reg_rand_vseq::type_id::create("reg_rand");
      pmu_pwr_matrix_vseq  mat_s = pmu_pwr_matrix_vseq::type_id::create("matrix");
      pmu_pwr_rand_vseq    pwr_s = pmu_pwr_rand_vseq::type_id::create("pwr_rand");
      pmu_bus_traffic_vseq bg    = pmu_bus_traffic_vseq::type_id::create("traffic");
      pmu_err_vseq         err_s = pmu_err_vseq::type_id::create("err");
      run_vseq(ral_s);
      if (!reg_s.randomize() with { n == 100; }) `uvm_fatal("TEST", "randomize failed")
      run_vseq(reg_s);
      fork
        bg.start(env.vsqr);
        begin
          run_vseq(mat_s);
          if (!pwr_s.randomize()) `uvm_fatal("TEST", "randomize failed")
          run_vseq(pwr_s);
          bg.stop = 1;
        end
      join
      run_vseq(err_s);
    endtask
  endclass

endpackage
// ---- end tests/pmu_test_pkg.sv ----

// ---- begin tb/pmu_dut_wrap.sv ----
// -----------------------------------------------------------------------------
// pmu_dut_wrap.sv - connects the DUT to the verification interfaces
//
// This is the only file that knows the DUT's port names. To verify the real
// PMU, compile a different file defining `pmu_dut_wrap` with the same two
// interface ports (select it with DUT_WRAP=... in scripts/Makefile) and set
// ISO_CLAMP / register-model differences in the test configuration.
// -----------------------------------------------------------------------------
`ifndef PMU_STUB_BUG_MODE
  `define PMU_STUB_BUG_MODE 0
`endif

module pmu_dut_wrap #(
  parameter logic [`PWR_ISO_W-1:0] ISO_CLAMP = 16'h00F0
) (
  input logic   clk_aon,
  input logic   rst_aon_n,
  axi_lite_if   axi,
  pwr_if        pwr
);

  pmu_stub #(
    .IRQ_W     (`PWR_IRQ_W),
    .ISO_W     (`PWR_ISO_W),
    .ISO_CLAMP (ISO_CLAMP),
    .BUG_MODE  (`PMU_STUB_BUG_MODE)
  ) u_pmu (
    .clk_aon          (clk_aon),
    .rst_aon_n        (rst_aon_n),
    .s_axi_awaddr     (axi.awaddr),
    .s_axi_awprot     (axi.awprot),
    .s_axi_awvalid    (axi.awvalid),
    .s_axi_awready    (axi.awready),
    .s_axi_wdata      (axi.wdata),
    .s_axi_wstrb      (axi.wstrb),
    .s_axi_wvalid     (axi.wvalid),
    .s_axi_wready     (axi.wready),
    .s_axi_bresp      (axi.bresp),
    .s_axi_bvalid     (axi.bvalid),
    .s_axi_bready     (axi.bready),
    .s_axi_araddr     (axi.araddr),
    .s_axi_arprot     (axi.arprot),
    .s_axi_arvalid    (axi.arvalid),
    .s_axi_arready    (axi.arready),
    .s_axi_rdata      (axi.rdata),
    .s_axi_rresp      (axi.rresp),
    .s_axi_rvalid     (axi.rvalid),
    .s_axi_rready     (axi.rready),
    .cpu_clk_en_o     (pwr.clk_en),
    .cpu_iso_en_o     (pwr.iso_en),
    .cpu_ret_en_o     (pwr.ret_en),
    .cpu_pwr_en_o     (pwr.pwr_en),
    .cpu_pwr_good_i   (pwr.pwr_good),
    .cpu_rst_n_o      (pwr.dom_rst_n),
    .dvfs_sel_o       (pwr.dvfs_sel),
    .cpu_wfi_i        (pwr.wfi),
    .wake_irq_i       (pwr.wake_irq),
    .pd_cpu_out_i     (pwr.dom_out),
    .pd_cpu_out_iso_o (pwr.dom_out_iso)
  );

endmodule
// ---- end tb/pmu_dut_wrap.sv ----

// ---- begin tb/axi_lite_bind.sv ----
// -----------------------------------------------------------------------------
// axi_lite_bind.sv - bind the AXI4-Lite protocol checker into every
// axi_lite_if instance.
// -----------------------------------------------------------------------------
bind axi_lite_if axi_lite_protocol_checker #(.MAX_WAIT(256)) u_axi_lite_chk (
  .aclk    (aclk),    .aresetn (aresetn),
  .awaddr  (awaddr),  .awprot  (awprot),  .awvalid (awvalid), .awready (awready),
  .wdata   (wdata),   .wstrb   (wstrb),   .wvalid  (wvalid),  .wready  (wready),
  .bresp   (bresp),   .bvalid  (bvalid),  .bready  (bready),
  .araddr  (araddr),  .arprot  (arprot),  .arvalid (arvalid), .arready (arready),
  .rdata   (rdata),   .rresp   (rresp),   .rvalid  (rvalid),  .rready  (rready)
);
// ---- end tb/axi_lite_bind.sv ----

// ---- begin tb/pmu_sva_bind.sv ----
// -----------------------------------------------------------------------------
// pmu_sva_bind.sv - hook for the PMU power-sequencing assertions
//
// The power-sequencing SVA and formal properties are owned by the PMU
// block-level verification branch and are deliberately NOT written here.
// Once that branch is merged, add its SVA file(s) to the compile with
//   make ... EXTRA_F=<path to their filelist> DEFINES=+define+PMU_POWER_SVA
// and adjust the bind target/instance below to the module and port names
// those files use. Nothing is bound unless PMU_POWER_SVA is defined.
// -----------------------------------------------------------------------------
`ifdef PMU_POWER_SVA
  `ifndef PMU_POWER_SVA_MODULE
    `define PMU_POWER_SVA_MODULE pmu_power_sva
  `endif
  `ifndef PMU_POWER_SVA_TARGET
    `define PMU_POWER_SVA_TARGET pmu
  `endif
  // Implicit .* connection: the SVA module's ports must match the PMU's
  // port names (the usual convention for bindable checkers).
  bind `PMU_POWER_SVA_TARGET `PMU_POWER_SVA_MODULE u_pmu_power_sva (.*);
`endif
// ---- end tb/pmu_sva_bind.sv ----

// ---- begin tb/pmu_tb_top.sv ----
// -----------------------------------------------------------------------------
// pmu_tb_top.sv - UVM testbench top for the PMU subsystem
// -----------------------------------------------------------------------------

module pmu_tb_top;

  import uvm_pkg::*;
  import pmu_test_pkg::*;

  localparam logic [`PWR_ISO_W-1:0] ISO_CLAMP = 16'h00F0;

  logic clk_aon   = 1'b0;
  logic rst_aon_n = 1'b1;

  always #5 clk_aon = ~clk_aon;          // 100 MHz always-on clock

  // Explicit falling edge at 1 ns so the asynchronous reset is applied
  // immediately (not only at the first clock edge).
  initial begin
    #1 rst_aon_n = 1'b0;
    repeat (5) @(posedge clk_aon);
    #1 rst_aon_n = 1'b1;
  end

  axi_lite_if axi_if (.aclk(clk_aon), .aresetn(rst_aon_n));
  pwr_if      pwr_vif (.clk(clk_aon), .rst_n(rst_aon_n));

  pmu_dut_wrap #(.ISO_CLAMP(ISO_CLAMP)) dut (
    .clk_aon   (clk_aon),
    .rst_aon_n (rst_aon_n),
    .axi       (axi_if),
    .pwr       (pwr_vif)
  );

  // AXI4-Lite protocol assertions are bound into axi_lite_if (tb/axi_lite_bind.sv)

  initial begin
    uvm_config_db#(virtual axi_lite_if)::set(null, "uvm_test_top", "axi_vif", axi_if);
    uvm_config_db#(virtual pwr_if)::set(null, "uvm_test_top", "pwr_vif", pwr_vif);
    uvm_config_db#(bit [`PWR_ISO_W-1:0])::set(null, "uvm_test_top", "iso_clamp", ISO_CLAMP);
    run_test();
  end

`ifdef PMU_DUMP
  initial begin
    $dumpfile("pmu_tb.vcd");
    $dumpvars(0, pmu_tb_top);
  end
`endif

endmodule
// ---- end tb/pmu_tb_top.sv ----
